#!/usr/bin/env bash
# test-cf-old-login-token-remint-bootstrap.sh — the #12931 Phase 5 token-slice bootstrap (bootstrap.sh in the
# feat-one-shot-12931-phase5-token-remint spec directory, generated by soleur:operator-bootstrap), plan
# 2026-11-27-chore-cf-phase5-old-login-token-remint-plan.md "## Guard Contract" and "## Test Scenarios".
#
#   bash tests/scripts/test-cf-old-login-token-remint-bootstrap.sh            every row, then every mutant
#   bash tests/scripts/test-cf-old-login-token-remint-bootstrap.sh --mutants  the mutation section only
#
# Properties: the plan's "## Guard Contract" (rows G1-*, G2-*, G3-*) and "## Test Scenarios" (rows S*); each
# row asserts the refusal TEXT or marker, never only an exit code.
#
# ASSEMBLY. A fixture git repository per world holds a copy of bootstrap.sh at its real relative path plus
# a committed stub of cloudflare-readonly.sh (the bootstrap runs only TRACKED files). PATH-stubbed `doppler` keeps state in $STUB_D/<project>/<config>/<NAME> files: `get
# --plain` prints the value plus ONE newline (the real CLI), `set` stores stdin exactly and logs
# `set <p>/<c>/<NAME> prev=<class of <NAME>_PREV at that moment>` (Guard 2's in-window order witness),
# `projects` / `configs` / `--only-names` list the state, `run` requires --no-fallback and execs with the
# --only-secrets names exported. The world holds the committed census floor (every soleur config of the real
# inventory file, which the fixture repo tracks, and every `# P5-PROJECT-FLOOR` project).
# PATH-stubbed `curl` answers both verify endpoints and GraphQL from the token's sentinel KIND; `gh` is
# stubbed and must never be called. Nothing reaches a network. Values are synthesized sentinels
# (cq-test-fixtures-synthesized-only); the ids are the public account/zone ids of the runbook id table.
#
# MUTATIONS (--mutants, and the tail of a full run): each `mkill` label names its mutant, row, step and the
# reason the row must observe (killed() rejects a red anywhere else, or for another reason). --mutants first runs the
# pristine arm of EVERY scored row on the unmutated script (exit 2 when any is red). HARNESS rows (`hred`)
# run a row on the REAL script under a deliberately broken stub and must go red the same way.
#
# LOCATION: this suite lives in tests/scripts and finds bootstrap.sh by glob, so an archive-kb move of the
# spec directory breaks nothing; exactly one match is required, else exit 2.
set -uo pipefail

export TMPDIR="${TMPDIR:-/var/tmp}"
export LC_ALL=C

MODE=full
case "${1:-}" in
  "") ;;
  --mutants) MODE=mutants ;;
  *) printf 'usage: %s [--mutants]\n' "$0" >&2; exit 2 ;;
esac

SUITE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(git -C "$SUITE_DIR" rev-parse --show-toplevel 2>/dev/null)" || { printf 'HARNESS: not in a git work tree\n' >&2; exit 2; }
_found=()   # a read loop, not mapfile: the suite stays runnable on bash 3.2
while IFS= read -r _f; do _found[${#_found[@]}]="$_f"; done < <(git -C "$REPO_ROOT" ls-files --cached --others --exclude-standard --full-name \
  '*feat-one-shot-12931-phase5-token-remint/bootstrap.sh')
[[ "${#_found[@]}" -eq 1 ]] || { printf 'HARNESS: expected exactly one phase5 token-remint bootstrap.sh, found %s\n' "${#_found[@]}" >&2; exit 2; }
SCRIPT_SRC="${REPO_ROOT}/${_found[0]}"
REL="${_found[0]}"  # the glob result, so this suite survives archive-kb moving the directory
LIB="${REPO_ROOT}/plugins/soleur/scripts/lib/operator-script.sh"
HOOK="${REPO_ROOT}/plugins/soleur/hooks/operator-stage-approval.sh"

assert_fixture_dir() {
  case "${1-}" in
    "") printf 'FATAL: fixture dir is EMPTY; git -C "" would operate on %s\n' "$PWD" >&2; exit 2 ;;
    */../*|*/..) printf 'FATAL: fixture dir %s contains ..; refusing\n' "$1" >&2; exit 2 ;;
    /proc/*|/sys/*|/dev/*) printf 'FATAL: fixture dir %s is a synthetic-fs path; refusing\n' "$1" >&2; exit 2 ;;
    /|//|/.) printf 'FATAL: fixture dir resolves to the filesystem root; refusing\n' >&2; exit 2 ;;
    /*) : ;;
    *)  printf 'FATAL: fixture dir %s is RELATIVE; refusing\n' "$1" >&2; exit 2 ;;
  esac
}

# shellcheck source=../../plugins/soleur/test/lib/git-fixture-env.sh
source "${REPO_ROOT}/plugins/soleur/test/lib/git-fixture-env.sh"

for bin in jq timeout git perl cmp sha256sum; do command -v "$bin" >/dev/null 2>&1 || { printf 'HARNESS: %s is required\n' "$bin" >&2; exit 2; }; done
[[ -r "$SCRIPT_SRC" && -r "$LIB" && -r "$HOOK" ]] || { printf 'HARNESS: script, library or hook missing\n' >&2; exit 2; }

PASS=0; FAIL=0
pass() { PASS=$((PASS + 1)); echo "  [ok] $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  [FAIL] $1" >&2; }
check() { if [[ "$2" -eq 0 ]]; then pass "$1"; else fail "$1 (last out: $(printf '%s' "${OUT:-}" | tr '\n' ' ' | cut -c1-400))"; fi; }

# Instrument self-test (ADR-193 shape): both helpers must move their counter, or nothing below means anything.
check "instrument self-test (pass arm)" 0 >/dev/null
check "instrument self-test (fail arm)" 1 >/dev/null 2>&1
if [[ "$PASS" -ne 1 || "$FAIL" -ne 1 ]]; then printf 'INSTRUMENT SELF-TEST FAILED (pass=%s fail=%s)\n' "$PASS" "$FAIL" >&2; exit 2; fi
FAIL=0   # PASS keeps the self-test's one pass; the floor at the bottom subtracts it (SELFTEST_PASSES)

SB="$(mktemp -d "${TMPDIR}/cf-p5-remint.XXXXXXXX")" || { printf 'HARNESS: mktemp failed\n' >&2; exit 2; }
trap 'chmod -R u+rwx "$SB" 2>/dev/null; rm -rf "$SB"' EXIT
ALL_OUT="$SB/all-output.log"; : > "$ALL_OUT"

readonly NZ=951ce525552201ec6c696b24251abed7 NA=66d4f93f7397f196544e9fe84c3557c2
readonly OZ=5af02a2f394e9ba6e0ea23c381a26b67
readonly OA=0123456789abcdef0123456789abcdef   # synthesized: any account id but the new one
readonly TFC=prd_terraform
# The keys and their pinned old-id prefixes come from the script's own `# P5-MANIFEST` lines (in the script a rotation
# edits only that block, CTO F18); the stubs read them from STUB_PINS. KA / KN / KP name the three consumers this suite models.
KEYS=(); STUB_PINS=""
while IFS='|' read -r _k _p _h; do
  _k="${_k#\# P5-MANIFEST }"; _k="${_k//[[:space:]]/}"; _p="${_p//[[:space:]]/}"
  KEYS[${#KEYS[@]}]="$_k"; STUB_PINS="${STUB_PINS:+$STUB_PINS }${_k}=${_p}"
done < <(grep -a '^# P5-MANIFEST ' "$SCRIPT_SRC")
readonly KEYS STUB_PINS
pin_of() { local e; for e in $STUB_PINS; do [[ "${e%%=*}" != "$1" ]] || { printf '%s\n' "${e#*=}"; return 0; }; done; return 1; }
readonly KA=CF_API_TOKEN_AUDIT KN=CF_API_TOKEN_ANALYTICS_READ KP=CF_API_TOKEN_PAGERULES_READ
for _k in "$KA" "$KN" "$KP"; do pin_of "$_k" >/dev/null || { printf 'HARNESS: the manifest has no %s line\n' "$_k" >&2; exit 2; }; done
# The census floor the bootstrap reads: its `# P5-PROJECT-FLOOR` line and the tracked soleur inventory file.
readonly INV_REL=apps/web-platform/infra/doppler-config-inventory.txt
FLOOR_PROJECTS=(); INV_CFGS=()
for _p in $(sed -n 's/^# P5-PROJECT-FLOOR //p' "$SCRIPT_SRC"); do FLOOR_PROJECTS[${#FLOOR_PROJECTS[@]}]="$_p"; done
while IFS= read -r _c; do INV_CFGS[${#INV_CFGS[@]}]="$_c"; done < <(grep -E '^[a-z0-9_]+$' "${REPO_ROOT}/${INV_REL}" | sort -u)
[[ "${#FLOOR_PROJECTS[@]}" -gt 0 && "${#INV_CFGS[@]}" -gt 0 ]] || { printf 'HARNESS: no census floor (project line or inventory) to model\n' >&2; exit 2; }
tok() { printf 'SYNTH-%s-%s-SENTINEL' "$1" "$2"; }   # tok <KIND> <KEY>

# --- stubs ----------------------------------------------------------------------
write_stubs() { # <bin-dir>
  local b="$1"; assert_fixture_dir "$b"; mkdir -p "$b"
  cat > "$b/doppler" <<'DOPPLER'
#!/usr/bin/env bash
# State: $STUB_D/<project>/<config>/<NAME> holds a value byte-exact. Flags in $STUB_D/.flags:
#   projects-empty | projects-fail          `doppler projects` answers [] / fails
#   unreadable.<p>.<c>                      the names listing of <p>/<c> fails
#   get-fails.<p>.<c>.<NAME>                a get of that (listed) name fails
#   corrupt.<p>.<c>.<NAME>                  a set of that name stores a DIFFERENT value
#   get-fails-after.<p>.<c>.<NAME>          holds N: every get of that name after the N-th (counted from the flag) fails
#   get-fail-nth.<p>.<c>.<NAME>             holds N: only the N-th get of that name fails
#   hide-project.<p> / hide-config.<p>.<c>  the listing silently omits that project / config (a narrowed credential)
#   configs-fail.<p>                        `doppler configs -p <p>` fails
#   names-array.<p>.<c>                     the names listing of <p>/<c> answers a JSON ARRAY of names
#   delete-noop                             a delete answers 0 and removes nothing
#   get-empty                               HARNESS H1: every get answers an empty value
#   get-as-prev                             HARNESS H3: a get of soleur/<c>/<NAME> (c != prd_terraform) serves
#                                           prd_terraform's <NAME>_PREV until that name is first set (the
#                                           classification reads are poisoned, the post-write read-back is not)
log() { printf '%s\t%s\n' "$1" "$2" >> "$STUB_LOG"; }
args=("$@"); proj=""; cfg=""; i=0; dd=-1; nofb=0; only=()
while (( i < ${#args[@]} )); do
  case "${args[i]}" in
    --) dd=$i; break ;;
    -p) proj="${args[i+1]:-}"; i=$((i+2)) ;;
    -c) cfg="${args[i+1]:-}"; i=$((i+2)) ;;
    --no-fallback) nofb=1; i=$((i+1)) ;;
    --only-secrets) only+=("${args[i+1]:-}"); i=$((i+2)) ;;
    *) i=$((i+1)) ;;
  esac
done
F="$STUB_D/.flags"; D="$STUB_D/$proj/$cfg"
cls() { [[ -f "$1" ]] || { echo absent; return; }; case "$(cat "$1")" in SYNTH-OLD-*) echo old ;; SYNTH-NEW*|SYNTH-ACCT-*) echo new ;; *) echo other ;; esac; }
case "${1:-} ${2:-}" in
  "projects --json")
    log read "projects"
    [[ ! -e "$F/projects-fail" ]] || exit 1
    if [[ -e "$F/projects-empty" ]]; then echo '[]'; exit 0; fi
    for e in $(ls -1 "$STUB_D"); do [[ -e "$F/hide-project.$e" ]] || echo "$e"; done | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({id: ., name: .})'; exit 0 ;;
  "configs -p")
    log read "configs $proj"
    [[ " $* " == *" --json "* ]] || exit 64
    [[ -n "$proj" && -d "$STUB_D/$proj" && ! -e "$F/configs-fail.$proj" ]] || exit 1
    for e in $(ls -1 "$STUB_D/$proj"); do [[ -e "$F/hide-config.$proj.$e" ]] || echo "$e"; done | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({name: ., root: false})'; exit 0 ;;
  "secrets --only-names")
    log read "list $proj/$cfg"
    [[ " $* " == *" --json "* ]] || exit 64
    [[ -n "$proj" && -n "$cfg" && -d "$D" && ! -e "$F/unreadable.$proj.$cfg" ]] || exit 1
    if [[ -e "$F/names-array.$proj.$cfg" ]]; then ls -1 "$D" | jq -R -s -c 'split("\n") | map(select(length > 0))'; exit 0; fi
    ls -1 "$D" | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({(.): {}}) | add // {}'; exit 0 ;;
  "secrets get")
    n="$3"; log read "get $proj/$cfg/$n"
    [[ " $* " == *" --plain "* ]] || exit 64
    [[ -f "$D/$n" && ! -e "$F/get-fails.$proj.$cfg.$n" ]] || exit 1
    if [[ -e "$F/get-fails-after.$proj.$cfg.$n" ]]; then
      printf 'x' >> "$F/get-count.$proj.$cfg.$n"
      [[ "$(wc -c < "$F/get-count.$proj.$cfg.$n")" -le "$(cat "$F/get-fails-after.$proj.$cfg.$n")" ]] || exit 1
    fi
    if [[ -e "$F/get-fail-nth.$proj.$cfg.$n" ]]; then
      printf 'x' >> "$F/get-nth.$proj.$cfg.$n"
      [[ "$(wc -c < "$F/get-nth.$proj.$cfg.$n")" -ne "$(cat "$F/get-fail-nth.$proj.$cfg.$n")" ]] || exit 1
    fi
    if [[ -e "$F/get-empty" ]]; then printf '\n'; exit 0; fi
    if [[ -e "$F/get-as-prev" && "$proj" == soleur && "$cfg" != prd_terraform && -f "$STUB_D/soleur/prd_terraform/${n}_PREV" && ! -e "$F/set-seen.$proj.$cfg.$n" ]]; then
      cat "$STUB_D/soleur/prd_terraform/${n}_PREV"; printf '\n'; exit 0
    fi
    cat "$D/$n"; printf '\n'; exit 0 ;;
  "secrets set")
    n="$3"; log mutating "set $proj/$cfg/$n prev=$(cls "$D/${n}_PREV")"; : > "$F/set-seen.$proj.$cfg.$n"
    [[ "$n" != *_PREV ]] || : > "$F/prev-set-seen"
    [[ " $* " == *" --silent "* ]] || exit 64
    mkdir -p "$D"
    if [[ -e "$F/corrupt.$proj.$cfg.$n" ]]; then { cat; printf 'CORRUPTED'; } > "$D/$n"; else cat > "$D/$n"; fi
    exit 0 ;;
  "secrets delete")
    n="$3"; log mutating "delete $proj/$cfg/$n"
    [[ " $* " == *" --yes "* ]] || exit 64
    [[ -e "$F/delete-noop" ]] || rm -f "$D/$n"; exit 0 ;;
  "run "*)
    # The real CLI: without --only-secrets every secret of the config (and the DOPPLER_* source names)
    # is injected; with it, only the named ones. Without --no-fallback it would write a snapshot of the
    # whole config to disk, so the stub refuses that call.
    log read "run $proj/$cfg only=$(IFS=,; printf '%s' "${only[*]}") nofallback=$nofb"
    [[ "$dd" -ge 0 && -d "$D" && "$nofb" -eq 1 ]] || exit 64
    keep() { local o; [[ "${#only[@]}" -gt 0 ]] || return 0; for o in "${only[@]}"; do [[ "$o" != "$1" ]] || return 0; done; return 1; }
    envs=()
    keep DOPPLER_PROJECT && envs+=("DOPPLER_PROJECT=$proj")
    keep DOPPLER_CONFIG && envs+=("DOPPLER_CONFIG=$cfg")
    keep DOPPLER_ENVIRONMENT && envs+=("DOPPLER_ENVIRONMENT=$cfg")
    for f in "$D"/*; do [[ -f "$f" ]] && keep "$(basename "$f")" && envs+=("$(basename "$f")=$(cat "$f")"); done
    exec env "${envs[@]}" "${args[@]:dd+1}" ;;
esac
log mutating "UNMODELLED $*"
exit 64
DOPPLER
  assert_fixture_dir "$b"
  cat > "$b/curl" <<'CURL'
#!/usr/bin/env bash
# Models curl on the bootstrap's call shape, `--config -` on stdin. Every URL is logged as `curl <url>`;
# a config line that is not the bearer header, the url, the JSON content type or a data line is an injected
# directive (`curl-config-extra`) and the call fails; no URL at all is `curl NOURL`, exit 2, no request.
# Verify endpoints (both): a token SYNTH-<KIND>-<KEY>-SENTINEL answers by KIND — OLD (id = the key's pinned
# prefix + 24 zeros), NEW / NEW2 / THIRD... (id = sha256 of the value), EXPIRED (status expired), all
# user-owned: /accounts/<new>/tokens/verify denies them (401 success:false) and /user/tokens/verify
# answers; ACCT is account-owned: the reverse. Anything else is denied. Flags in $STUB_D/.flags:
#   revoked-old  every OLD token is denied on both endpoints (the simulated revoke)
#   curl-429 / curl-503  every verify read answers 429 JSON success:false / 503 HTML (no verdict)
#   curl-down    every request is a transport failure (exit 7)
#   graphql-mismatch     the GraphQL answer names no zone and carries one error
#   graphql-errors       the GraphQL answer names the new zone AND carries one error
#   curl-403-html        every verify read answers 403 with an HTML body (no verdict)
# Kind OLDEXP answers the key's pinned id with status expired (an expired old token).
#   old-denied-after-prev-set / old-unreachable-after-prev-set  once any *_PREV was set, every OLD token is
#                        denied (401 JSON) / answers 503 HTML: the old token dies inside the swap window
# The argv must be EXACTLY the bootstrap's (`--disable` first, no proxy, a time and redirect cap, the status
# line, the config on stdin); any other argv is `curl-argv-bad`, exit 64, no request.
# GraphQL: an ANALYTICS token of kind NEW* or ACCT gets the new zone tag and errors:null.
set -f
F="$STUB_D/.flags"
urls=(); tok=""; extra=0; data=0; ct=0
hre='^header = "Authorization: Bearer ([^"]*)"$'; ure='^url = "([^"]*)"$'
for a in "$@"; do case "$a" in https://*) urls+=("$a") ;; esac; done
want=(--disable --noproxy '*' -sS --max-time 30 --max-redirs 0 -w '\n%{http_code}' --config -)
[[ "$*" == "${want[*]}" ]] || { printf 'read\tcurl-argv-bad\n' >> "$STUB_LOG"; exit 64; }
while IFS= read -r line; do
  if [[ "$line" =~ $hre ]]; then tok="${BASH_REMATCH[1]}"
  elif [[ "$line" =~ $ure ]]; then [[ -z "${BASH_REMATCH[1]}" ]] || urls+=("${BASH_REMATCH[1]}")
  elif [[ "$line" == 'header = "Content-Type: application/json"' ]]; then ct=1
  elif [[ "$line" == 'data = "'*'"' ]]; then data=1
  elif [[ -n "$line" ]]; then extra=1
  fi
done < <(cat)
[[ "$extra" -eq 0 ]] || printf 'read\tcurl-config-extra\n' >> "$STUB_LOG"
[[ "${#urls[@]}" -gt 0 ]] || { printf 'read\tcurl NOURL\n' >> "$STUB_LOG"; exit 2; }
for u in "${urls[@]}"; do printf 'read\tcurl %s\n' "$u" >> "$STUB_LOG"; done
[[ "$extra" -eq 0 && "${#urls[@]}" -eq 1 ]] || exit 64
[[ ! -e "$F/curl-down" ]] || exit 7
wo=0; for a in "$@"; do [[ "$a" == -w ]] && wo=1; done
reply() { printf '%s' "$2"; [[ "$wo" -eq 0 ]] || printf '\n%s' "$1"; exit 0; }
api=https://api.cloudflare.com/client/v4; u="${urls[0]}"
deny() { reply 401 '{"success":false,"errors":[{"code":1000,"message":"Invalid API Token"}]}'; }
kre='^SYNTH-([A-Z0-9]+)-(CF_API_TOKEN_[A-Z_]+)-SENTINEL$'
kind=""; key=""
if [[ "$tok" =~ $kre ]]; then kind="${BASH_REMATCH[1]}"; key="${BASH_REMATCH[2]}"; fi
pin() { local e; for e in ${STUB_PINS:-}; do [[ "${e%%=*}" != "$1" ]] || { echo "${e#*=}"; return; }; done; echo 0000ffff; }
tid() { if [[ "$kind" == OLD || "$kind" == OLDEXP ]]; then printf '%s000000000000000000000000' "$(pin "$key")"; else printf '%s' "$tok" | sha256sum | cut -c1-32; fi; }
case "$u" in
  "$api/accounts/66d4f93f7397f196544e9fe84c3557c2/tokens/verify"|"$api/user/tokens/verify")
    [[ ! -e "$F/curl-429" ]] || reply 429 '{"success":false,"errors":[{"code":971,"message":"Please wait and consider throttling your request speed"}]}'
    [[ ! -e "$F/curl-503" ]] || reply 503 '<html><body>503 Service Unavailable</body></html>'
    [[ ! -e "$F/curl-403-html" ]] || reply 403 '<html><body>403 Forbidden</body></html>'
    [[ -n "$kind" ]] || deny
    [[ "$kind" != OLD || ! -e "$F/revoked-old" ]] || deny
    if [[ "$kind" == OLD && -e "$F/prev-set-seen" ]]; then
      [[ ! -e "$F/old-denied-after-prev-set" ]] || deny
      [[ ! -e "$F/old-unreachable-after-prev-set" ]] || reply 503 '<html><body>503 Service Unavailable</body></html>'
    fi
    acct=0; [[ "$kind" == ACCT ]] && acct=1
    if [[ "$u" == */accounts/* ]]; then [[ "$acct" -eq 1 ]] || deny; else [[ "$acct" -eq 0 ]] || deny; fi
    st=active; [[ "$kind" == EXPIRED || "$kind" == OLDEXP ]] && st=expired
    reply 200 "{\"success\":true,\"result\":{\"id\":\"$(tid)\",\"status\":\"${st}\",\"expires_on\":\"2027-02-20T00:00:00Z\"}}" ;;
  "$api/graphql")
    [[ "$data" -eq 1 && "$ct" -eq 1 ]] || exit 64
    if [[ "$key" == CF_API_TOKEN_ANALYTICS_READ && "$kind" =~ ^(NEW[0-9]*|ACCT)$ && -e "$F/graphql-errors" ]]; then
      reply 200 '{"data":{"viewer":{"zones":[{"zoneTag":"951ce525552201ec6c696b24251abed7"}]}},"errors":[{"message":"partial"}]}'
    fi
    if [[ "$key" == CF_API_TOKEN_ANALYTICS_READ && "$kind" =~ ^(NEW[0-9]*|ACCT)$ && ! -e "$F/graphql-mismatch" ]]; then
      reply 200 '{"data":{"viewer":{"zones":[{"zoneTag":"951ce525552201ec6c696b24251abed7"}]}},"errors":null}'
    fi
    reply 200 '{"data":{"viewer":{"zones":[]}},"errors":[{"message":"not authorized for that zone"}]}' ;;
esac
exit 64
CURL
  assert_fixture_dir "$b"
  cat > "$b/gh" <<'GH'
#!/usr/bin/env bash
# No stage may call GitHub: any call is recorded and refused.
printf 'gh %s\n' "$*" >> "$STUB_D/.gh-called"
exit 64
GH
  chmod +x "$b/doppler" "$b/curl" "$b/gh"
}

# make_repo <dir> <bootstrap-src> — a fixture repository tracking the script and the two tool stubs.
make_repo() {
  local r="$1" src="$2"; assert_fixture_dir "$r"
  mkdir -p "$r/$(dirname "$REL")" "$r/plugins/soleur/scripts" "$r/$(dirname "$INV_REL")"
  cp "$src" "$r/$REL"
  cp "${REPO_ROOT}/${INV_REL}" "$r/$INV_REL"
  cat > "$r/plugins/soleur/scripts/cloudflare-readonly.sh" <<'RO'
#!/usr/bin/env bash
# Stand-in for the consumer wrapper: refuses outside soleur/prd_terraform, reads only its bound variable,
# and prints a verdict line plus a JSON projection that must never reach the bootstrap's output.
printf 'read\tconsumer %s\n' "$*" >> "$STUB_LOG"
[[ "${DOPPLER_PROJECT:-}" == soleur && "${DOPPLER_CONFIG:-}" == prd_terraform ]] || { echo 'refused source' >&2; exit 64; }
sub="${1:-}"
case "$sub" in
  pagerules-ssl) v="${CF_API_TOKEN_PAGERULES_READ:-}"; k=CF_API_TOKEN_PAGERULES_READ ;;
  change-history) v="${CF_API_TOKEN_AUDIT:-}"; k=CF_API_TOKEN_AUDIT ;;
  analytics-health) v="${CF_API_TOKEN_ANALYTICS_READ:-}"; k=CF_API_TOKEN_ANALYTICS_READ
    if [[ -e "$STUB_D/.flags/analytics-api-error" ]]; then echo "cloudflare-readonly: analytics-health unverified - api-error (graphql: quantile fields are not available on this plan)"; exit 14; fi ;;
  *) exit 64 ;;
esac
for e in $(compgen -e); do case "$e" in CF_API_TOKEN*) [[ "$e" == "$k" ]] || { echo "cloudflare-readonly: ${sub} unverified - env-too-wide"; exit 11; } ;; esac; done
[[ ! -e "$STUB_D/.flags/consumer-fail.$sub" ]] || { echo "cloudflare-readonly: ${sub} unverified - token-lacks-scope"; exit 11; }
if [[ "$v" =~ ^SYNTH-(NEW[0-9]*|ACCT|EXPIRED)-${k}-SENTINEL$ ]]; then
  echo "cloudflare-readonly: ${sub} ok"; echo '{"count":2,"actor":"synth-actor@example.invalid","ip":"192.0.2.7"}'; exit 0
fi
echo "cloudflare-readonly: ${sub} unverified - token-lacks-scope"; exit 11
RO
  chmod +x "$r/plugins/soleur/scripts/cloudflare-readonly.sh"
  printf '.env\n.env.tmp.*\nbootstrap-runs.jsonl\n' > "$r/.gitignore"
  (
    git_fixture_env "$r" || exit 1
    cd "$r" && git init -q . && git add -A && git commit -qm fixture ) >/dev/null 2>&1 || { printf 'HARNESS: fixture repo failed\n' >&2; exit 2; }
}

# world <name> [<bootstrap-src>] — fresh state (the common configs, no manifest key yet), a fixture repo.
# HARNESS_FLAG, when set by the caller, is raised in the doppler stub for the whole world.
HARNESS_FLAG=""
world() {
  local src="${2:-$SCRIPT_SRC}"
  STEP="world"
  W="$SB/w-$1-$RANDOM"; rm -rf "$W"; mkdir -p "$W/state/.flags" "$W/xdg"
  write_stubs "$W/bin"
  make_repo "$W/repo" "$src"
  S="$W/repo/$REL"
  STUB_D="$W/state"; STUB_LOG="$W/calls.log"; : > "$STUB_LOG"
  [[ -z "$HARNESS_FLAG" ]] || : > "$STUB_D/.flags/$HARNESS_FLAG"
  sv soleur "$TFC" CF_ZONE_ID "$NZ"; sv soleur "$TFC" CF_ACCOUNT_ID "$NA"; sv soleur "$TFC" OTHER_KEY unrelated
  sv soleur "$TFC" CF_API_TOKEN "SYNTH-WRITE-CAPABLE-SENTINEL"   # a write-capable token the read keys must never equal
  sv soleur dev CF_ZONE_ID "$NZ"; sv soleur dev OTHER_KEY unrelated
  sv soleur dev_personal OTHER_KEY unrelated     # its CF_API_TOKEN_AUDIT copy was deleted by hold (CTO F20)
  sv soleur dev_scheduled OTHER_KEY unrelated    # same
  sv soleur prd OTHER_KEY unrelated
  sv other ci OTHER_KEY unrelated
  sv soleur-infra-privileged prd CF_API_TOKEN_ORIGIN_CA "SYNTH-PRIV-ORIGIN-SENTINEL"
  sv soleur-infra-privileged prd CF_API_TOKEN_R2 "SYNTH-PRIV-R2-SENTINEL"
  # The committed census floor: every inventory config of soleur, and one config of every floor project.
  local fc fp
  for fc in "${INV_CFGS[@]}"; do [[ -d "$STUB_D/soleur/$fc" ]] || sv soleur "$fc" OTHER_KEY unrelated; done
  for fp in "${FLOOR_PROJECTS[@]}"; do [[ -d "$STUB_D/$fp" ]] || sv "$fp" prd OTHER_KEY unrelated; done
  CHILD_ENV=("PATH=$W/bin:$PATH" "SOLEUR_OP_LIB=$LIB" "ENV_FILE=$W/xdg/.env" "SOLEUR_BOOTSTRAP_LEDGER=$W/ledger.jsonl"
             "STUB_D=$STUB_D" "STUB_LOG=$STUB_LOG" "STUB_PINS=$STUB_PINS" "XDG_STATE_HOME=$W/xdg"
             "GIT_CEILING_DIRECTORIES=$SB")   # a TMPDIR inside some work tree must not leak that tree into a fixture
}
sv() { mkdir -p "$STUB_D/$1/$2"; printf '%s' "$4" > "$STUB_D/$1/$2/$3"; }   # sv <proj> <cfg> <NAME> <value>
rmv() { rm -f "$STUB_D/$1/$2/$3"; }
val() { cat "$STUB_D/$1/$2/$3" 2>/dev/null; }
has() { [[ -f "$STUB_D/$1/$2/$3" ]]; }
flag() { : > "$STUB_D/.flags/$1"; }
# seed_staged — the mint sitting is done: every <KEY>_NEXT holds a new token, <KEY> and dev's AUDIT the old one.
seed_staged() {
  local k
  for k in "${KEYS[@]}"; do sv soleur "$TFC" "$k" "$(tok OLD "$k")"; sv soleur "$TFC" "${k}_NEXT" "$(tok NEW "$k")"; done
  sv soleur dev "$KA" "$(tok OLD "$KA")"
}
# seed_swapped — swap and holder-copies are done: <KEY>_PREV old, <KEY> new, no _NEXT, dev's AUDIT new.
seed_swapped() {
  local k
  for k in "${KEYS[@]}"; do sv soleur "$TFC" "${k}_PREV" "$(tok OLD "$k")"; sv soleur "$TFC" "$k" "$(tok NEW "$k")"; done
  sv soleur dev "$KA" "$(tok NEW "$KA")"
}

OUT=""; RC=0; WHY=""
# Every child runs with the session and approval-hook variables and the git location variables removed, so a
# developer shell, a harness session or a linked worktree changes nothing about what a row observes.
# The bootstrap refuses EVERY exported GIT_* variable (bar five inert ones), BASH_ENV and ENV by class, so the
# scrub is by prefix too: an inherited GIT_PAGER or GIT_SSH_COMMAND in a developer shell must not red every row
# (the rows that model an inherited variable add it back with run_with).
UNSET_ENV=()
for _v in CLAUDE_PLUGIN_ROOT CLAUDE_CODE_ENTRYPOINT CLAUDECODE OPENCODE SOLEUR_DISABLE_OPERATOR_STAGE_APPROVAL_HOOK \
          DOPPLER_TOKEN DOPPLER_PROJECT DOPPLER_CONFIG DOPPLER_ENVIRONMENT DOPPLER_API_HOST BASH_ENV ENV "${GIT_LOCATION_VARS[@]}" \
          DOPPLER_CONFIG_DIR HTTPS_PROXY https_proxy HTTP_PROXY http_proxy ALL_PROXY all_proxy SSL_CERT_FILE SSL_CERT_DIR \
          $(compgen -e | sed -n 's/^\(GIT_[A-Za-z0-9_]*\)$/\1/p'); do
  UNSET_ENV+=(-u "$_v")
done
# observe — after every child: WHY is the reasons and markers the run printed (killed() names the one a mutant
# must produce), and a READ stage that made any mutating doppler call is forced red (rc 97, why read-stage-wrote).
observe() { # <mutating-calls-before> <read-stage 0|1>
  WHY="rc=${RC} $(grep -oE '^SOLEUR_[A-Z0-9_]+|reason=[a-z-]+|need=[a-z-]+' <<<"$OUT" | sort -u | tr '\n' ' ')"
  if [[ "$2" -eq 1 && "$(mut)" -gt "$1" ]]; then RC=97; WHY="read-stage-wrote ${WHY}"; OUT="read-stage-wrote: ${OUT}"; fi
  printf '%s\n' "$OUT" >> "$ALL_OUT"
}
run() {
  local before rs=0; before="$(mut)"
  [[ " $* " == *" --stage verify "* || " $* " == *" --stage inventory "* ]] && rs=1
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" timeout 120 bash "$S" "$@" </dev/null 2>&1)"; RC=$?
  observe "$before" "$rs"
}
run_with() { # <VAR=value>... -- <bootstrap args> — run() with extra environment for the child
  local -a extra=(); local before
  while [[ "$1" != -- ]]; do extra+=("$1"); shift; done; shift
  before="$(mut)"
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" "${extra[@]}" timeout 120 bash "$S" "$@" </dev/null 2>&1)"; RC=$?
  observe "$before" 0
}
digest() { sed -n 's/^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]* operations=[0-9]* digest=\([0-9a-f]*\)$/\1/p' <<<"$OUT"; }
ops() { sed -n 's/^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]* operations=\([0-9]*\) digest=.*$/\1/p' <<<"$OUT"; }
mut() { grep -c "^mutating" "$STUB_LOG" || true; }
# STEP: a row names the assertion it is about to make (`at <step>`); a row that returns non-zero leaves
# STEP at the step it stopped on. killed <rc> <step>: a mutation counts as killed only when the row went
# red AT the step its header names, never during setup.
STEP=""
at() { STEP="$1"; }
# killed <rc> <step> <why-ere> — red, AT the named step, and the last run printed the named reason (an ERE over
# WHY). Any red is not enough: a stub with no network reds most rows at their step for another reason.
killed() {
  [[ "$1" -ne 0 && "$STEP" == "$2" ]] || { echo "    row rc=$1 stopped at step '${STEP}', want '$2'"; return 1; }
  grep -qE -- "$3" <<<"$WHY" || { echo "    row red at '${STEP}' but its last run printed '${WHY}', want /$3/"; return 1; }
}
# approve <stage>: plan, the REAL hook mints a receipt for the exact apply command, then the rewritten
# command runs as the harness would run it. Leaves OUT/RC of the apply.
approve() {
  local stage="$1" d
  run --stage "$stage"
  d="$(digest)"
  [[ -n "$d" && "$(ops)" -gt 0 ]] || { OUT="approve(): no plan with operations for ${stage}: ${OUT}"; RC=99; WHY="approve-no-plan ${WHY}"; return; }
  apply_with_receipt "$stage" "$d"
}
# apply_with_receipt <stage> <digest>: the REAL hook mints a receipt for that exact apply command, which then runs.
apply_with_receipt() {
  local stage="$1" d="$2" cmd in newc
  cmd="bash $S --stage $stage --apply --plan-digest $d"
  in="$(jq -nc --arg c "$cmd" '{tool_name:"Bash",tool_input:{command:$c},permission_mode:"default",session_id:"s",cwd:"/",hook_event_name:"PreToolUse"}')"
  newc="$(printf '%s' "$in" | env "${UNSET_ENV[@]}" "XDG_STATE_HOME=$W/xdg" CLAUDE_CODE_ENTRYPOINT=cli bash "$HOOK" | jq -r '.hookSpecificOutput.updatedInput.command // empty')"
  [[ -n "$newc" ]] || { OUT="approve(): the hook minted nothing for: ${cmd}"; RC=98; WHY="approve-no-receipt"; return; }
  local before; before="$(mut)"
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" timeout 120 bash -c "$newc" </dev/null 2>&1)"; RC=$?
  observe "$before" 0
}
# copy_with <src> <dst> — a copy of the script with a perl edit (stdin) that must land; rc 1 when it did not land
# (the copy equals the source), rc 2 when the copy does not parse.
copy_with() {
  local src="$1" dst="$2" prog; prog="$(cat)"
  assert_fixture_dir "$dst"
  cp "$src" "$dst"; perl -0777 -pi -e "$prog" "$dst"
  ! cmp -s "$dst" "$src" || return 1
  bash -n "$dst" 2>/dev/null || return 2
}
has_line() { grep -qxF -- "$1" <<<"$OUT"; }
vok() { has_line "SOLEUR_P5_VERIFY key=$1 verdict=ok"; }
vfail_is() { has_line "SOLEUR_P5_VERIFY key=$1 verdict=fail reason=$2"; }
# new_id_of <KIND> <KEY> — the 8-character id the curl stub answers for a non-OLD token: sha256 of the value.
new_id_of() { printf '%s' "$(tok "$1" "$2")" | sha256sum | cut -c1-8; }
# ready <key> [owner] — the exact REVOKE_READY line: the pinned old id, the NEW token's own id (kind ACCT when
# account-owned, else NEW), its owner, and the old token's owner (every OLD sentinel is user-owned).
ready() {
  local o="${2:-user}" kind=NEW; [[ "$o" == account ]] && kind=ACCT
  has_line "SOLEUR_P5_REVOKE_READY key=$1 old_id=$(pin_of "$1") new_id=$(new_id_of "$kind" "$1") owner=${o} old_owner=user"
}
noready() { ! grep -q "^SOLEUR_P5_REVOKE_READY key=$1 " <<<"$OUT"; }
logged() { grep -qE -- "$1" "$STUB_LOG"; }
set_lines() { grep -cE "^mutating	set soleur/${1}/${2} prev=" "$STUB_LOG" || true; }   # <cfg> <NAME>
# leak_scan <file> — rc 0 when no line carries 24+ consecutive lowercase hex characters, except a line that is
# EXACTLY one of the library's approval lines: the plan line, the apply-command line, the apply command itself and
# the approval-required line. Their hex is a hash of operation names or of the command text, never of a value.
# ONE awk process reads the whole file: a `grep -v | grep -q` pipeline under pipefail reports a leak as a pass on
# SIGPIPE. Only the line number and the first word of a hit are printed, never the hex.
leak_scan() {
  local h64; h64="$(printf '[0-9a-f]%.0s' $(seq 1 64))"
  LC_ALL=C awk -v hex="$(printf '[0-9a-f]%.0s' $(seq 1 24))" \
    -v e1="^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]+ operations=[0-9]+ digest=${h64}\$" \
    -v e2="^SOLEUR_BOOTSTRAP_APPLY_COMMAND stage=[^ ]+ approval_digest=${h64}\$" \
    -v e3="^  bash [^ ]+ --stage [^ ]+ --apply --plan-digest ${h64}\$" \
    -v e4="^SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=[^ ]+ approval_digest=${h64} surface=[a-z-]+\$" '
    $0 ~ e1 || $0 ~ e2 || $0 ~ e3 || $0 ~ e4 { next }
    $0 ~ hex { bad = 1; if (shown++ < 3) printf "    leak: line %d of %s (first word %s)\n", NR, FILENAME, $1 > "/dev/stderr" }
    END { exit bad }' "$1"
}

# ==================================================================================================
# Guard 1 rows — verify's census and REVOKE_READY (world: seed_swapped, a compliant post-swap state)
# ==================================================================================================
row_g1_1_floor() { # <src>
  local k
  world g1-1 "$1"; seed_swapped; flag projects-empty
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && grep -qF 'SOLEUR_P5_CENSUS_FLOOR verdict=fail' <<<"$OUT" || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-floor && noready "$k" || return 1; done
}
row_g1_2_blind() { # <src> — the census reads the raw CLI output (newline kept), so it sees no old copy
  local k b="$SB/blind-$RANDOM.sh"
  at setup
  copy_with "$1" "$b" <<'PERL' || return 1
s{  HD="\$\(set -o pipefail; plain_get "\$1" "\$2" "\$3" \| soleur_approval_sha256\)"}{  HD="\$(set -o pipefail; doppler secrets get "\$3" -p "\$1" -c "\$2" --plain 2>/dev/null | soleur_approval_sha256)"}
PERL
  world g1-2 "$b"; seed_swapped
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-blind && noready "$k" || return 1; done
}
row_g1_3_second_member() { # <src> — dev holds the new token, dev_personal (the next config) still the old one
  world g1-3 "$1"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" old-holder && noready "$KA" \
    && has_line "SOLEUR_P5_OLD_HOLDER key=${KA} holder=soleur/dev_personal/${KA}" \
    && has_line "SOLEUR_P5_HOLDER project=soleur config=dev key=${KA} value=new"
}
row_g1_4_unlisted_project() { # <src> — project other, config ci (in no manifest) holds the old value
  world g1-4 "$1"; seed_swapped; sv other ci "$KA" "$(tok OLD "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" old-holder && noready "$KA" && has_line "SOLEUR_P5_OLD_HOLDER key=${KA} holder=other/ci/${KA}" || return 1
  at no-write
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 0 && "$(ops)" == 0 && "$(mut)" -eq 0 ]] && ! grep -q 'SOLEUR_BOOTSTRAP_PLAN_OP.*ci/' <<<"$OUT"
}
row_g1_5_expired() { # <src> — compliant except <KEY> verifies a new id with status=expired
  world g1-5 "$1"; seed_swapped
  sv soleur "$TFC" "$KA" "$(tok EXPIRED "$KA")"; sv soleur dev "$KA" "$(tok EXPIRED "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" key-not-active && noready "$KA"
}
row_g1_6_prev_new() { # <src> — <KEY>_PREV holds the NEW value (the #13080 order)
  world g1-6 "$1"; seed_swapped; sv soleur "$TFC" "${KA}_PREV" "$(tok NEW "$KA")"
  at source
  run --stage verify
  has_line "SOLEUR_P5_REFERENCE key=${KA} source=none" && noready "$KA" || return 1
  at verdict
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" no-reference
}
row_g1_7_get_error() { # <src> — one config's get on a listed name errors
  world g1-7 "$1"; seed_swapped; sv other ci "$KA" "$(tok NEW "$KA")"; flag "get-fails.other.ci.${KA}"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_UNREADABLE project=other config=ci name=${KA}" && vfail_is "$KA" census-unreadable && noready "$KA"
}
row_g1_mustpass() { # <src> — other/ci holds the NEW value and soleur/prd lacks the key: ok plus REVOKE_READY
  local k
  world g1-pass "$1"; seed_swapped; sv other ci "$KA" "$(tok NEW "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 0 ]] && has_line 'SOLEUR_P5_VERIFY verdict=ok' || return 1
  for k in "${KEYS[@]}"; do vok "$k" && ready "$k" || return 1; done
  has_line "SOLEUR_P5_HOLDER project=soleur config=prd key=${KA} value=absent" \
    && has_line "SOLEUR_P5_HOLDER project=other config=ci key=${KA} value=new" \
    && has_line "SOLEUR_P5_CENSUS key=${KA} configs_read=$(find "$STUB_D" -mindepth 2 -maxdepth 2 -type d | wc -l) old_hits=1" || return 1
  at consumers
  has_line "SOLEUR_P5_CONSUMER key=${KA} sub=change-history gating=yes rc=0 line=cloudflare-readonly: change-history ok" \
    && has_line "SOLEUR_P5_CONSUMER key=${KP} sub=pagerules-ssl gating=yes rc=0 line=cloudflare-readonly: pagerules-ssl ok" \
    && has_line "SOLEUR_P5_CONSUMER key=${KN} sub=analytics-health gating=no rc=0 line=cloudflare-readonly: analytics-health ok" \
    && logged "^read	run soleur/${TFC} only=DOPPLER_PROJECT,DOPPLER_CONFIG,CF_ZONE_ID,CF_ACCOUNT_ID,${KA} nofallback=1$"
}

row_g1_8_hidden_holder() { # <src> — AUDIT's manifest names soleur/dev_hidden, a config the listing does not show
  local b="$SB/hidden-$RANDOM.sh"
  at setup
  copy_with "$1" "$b" <<'PERL' || return 1
s{(# P5-MANIFEST CF_API_TOKEN_AUDIT +\| [0-9a-f]{8} +\| soleur/prd_terraform soleur/dev)\n}{$1 soleur/dev_hidden\n}
PERL
  world g1-8 "$b"; seed_swapped
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line 'SOLEUR_P5_FLOOR_MISSING name=soleur/dev_hidden' && vfail_is "$KA" census-floor && noready "$KA"
}
row_g1_9_names_unreadable() { # <src> — other/ci holds the old value and its names listing fails
  world g1-9 "$1"; seed_swapped; sv other ci "$KA" "$(tok OLD "$KA")"; flag unreadable.other.ci
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line 'SOLEUR_P5_UNREADABLE project=other config=ci' && vfail_is "$KA" census-unreadable && noready "$KA"
}
row_g1_10_configs_unreadable() { # <src> — project other (outside the floor) holds the old value and its configs listing fails
  local k
  world g1-10 "$1"; seed_swapped; sv other ci "$KA" "$(tok OLD "$KA")"; flag configs-fail.other
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line 'SOLEUR_P5_UNREADABLE project=other config=-' || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-unreadable && noready "$k" || return 1; done
}
row_g1_11_next_staged() { # <src> — swapped, but a second new token is staged as AUDIT_NEXT
  world g1-11 "$1"; seed_swapped; sv soleur "$TFC" "${KA}_NEXT" "$(tok NEW2 "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" next-staged && noready "$KA"
}
row_g1_12_names_array() { # <src> — other/ci holds the old value and its names listing answers an ARRAY
  world g1-12 "$1"; seed_swapped; sv other ci "$KA" "$(tok OLD "$KA")"; flag names-array.other.ci
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line 'SOLEUR_P5_UNREADABLE project=other config=ci' && vfail_is "$KA" census-unreadable && noready "$KA"
}
row_g1_13_floor() { # <src> <project|config> — the listing silently drops soleur-infra-privileged, or soleur/dev_personal
  local k want
  world "g1-13-$2" "$1"; seed_swapped
  if [[ "$2" == project ]]; then flag hide-project.soleur-infra-privileged; want=soleur-infra-privileged
  else flag hide-config.soleur.dev_personal; want=soleur/dev_personal; fi
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_FLOOR_MISSING name=${want}" && has_line 'SOLEUR_P5_CENSUS_FLOOR verdict=fail reason=floor-missing' || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-floor && noready "$k" || return 1; done
}
row_g1_14_holder_not_new() { # <src> <absent|other> — dev (AUDIT's manifest holder) lacks the key, or holds a third value
  world "g1-14-$2" "$1"; seed_swapped
  if [[ "$2" == absent ]]; then rmv soleur dev "$KA"; else sv soleur dev "$KA" "$(tok THIRD "$KA")"; fi
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_HOLDER_NOT_NEW key=${KA} holder=soleur/dev value=$2" && vfail_is "$KA" holder-not-new && noready "$KA" && vok "$KN"
}
row_g1_15_prev_expired() { # <src> — _PREV verifies the pinned id, but with status expired (CTO F13 needs it active)
  world g1-15 "$1"; seed_swapped; sv soleur "$TFC" "${KA}_PREV" "$(tok OLDEXP "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_REFERENCE key=${KA} source=PREV" && vfail_is "$KA" prev-not-active && noready "$KA"
}

# ==================================================================================================
# Guard 2 rows — swap (world: seed_staged)
# ==================================================================================================
REFUSE_PIN="does not verify the pinned id dd6d1427, so a swap would lose the only copy the revoke reads"
row_g2_1_key_not_pinned() { # <src> — <KEY> is not the pinned id and no _PREV exists
  world g2-1 "$1"; seed_staged; sv soleur "$TFC" "$KA" "$(tok THIRD "$KA")"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' && grep -qF "$REFUSE_PIN" <<<"$OUT" || return 1
  at zero-writes
  approve swap
  [[ "$(mut)" -eq 0 && "$(val soleur "$TFC" "$KA")" == "$(tok THIRD "$KA")" ]] && has soleur "$TFC" "${KA}_NEXT" && ! has soleur "$TFC" "${KA}_PREV"
}
row_g2_2_prev_by_name() { # <src> — a _PREV exists holding a non-pinned value, <KEY> not pinned
  world g2-2 "$1"; seed_staged
  sv soleur "$TFC" "${KA}_PREV" "$(tok THIRD "$KA")"; sv soleur "$TFC" "$KA" "$(tok NEW2 "$KA")"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' && grep -qE "^SOLEUR_P5_PREV_LIVE key=${KA} id=[0-9a-f]{8}$" <<<"$OUT" || return 1
  at zero-writes
  approve swap
  [[ "$(mut)" -eq 0 && "$(val soleur "$TFC" "${KA}_PREV")" == "$(tok THIRD "$KA")" ]]
}
row_g2_3_prev_copy_mismatch() { # <src> [PREV|KEY] — which write the stub corrupts (KEY is harness H2)
  local target="${2:-PREV}" n="${KA}_PREV"
  [[ "$target" == KEY ]] && n="$KA"
  world g2-3 "$1"; seed_staged; flag "corrupt.soleur.${TFC}.${n}"
  : > "$STUB_LOG"; approve swap
  at no-key-write
  [[ "$(set_lines "$TFC" "$KA")" -eq 0 ]] || return 1
  at mismatch
  has_line "SOLEUR_P5_COPY_MISMATCH src=${TFC}/${KA} dst=${TFC}/${KA}_PREV" || return 1
  at next-kept
  [[ "$(val soleur "$TFC" "${KA}_NEXT")" == "$(tok NEW "$KA")" && "$(val soleur "$TFC" "$KA")" == "$(tok OLD "$KA")" ]] || return 1
  at stops
  [[ "$RC" -ne 0 ]] && has_line "SOLEUR_BOOTSTRAP_STAGE_FAILED stage=swap rc=1"
}
row_g2_4_second_key_fails() { # <src> — key 1 swaps, key 2's _PREV copy fails, key 3 must stay untouched
  world g2-4 "$1"; seed_staged; flag "corrupt.soleur.${TFC}.${KN}_PREV"
  : > "$STUB_LOG"; approve swap
  at mismatch
  has_line "SOLEUR_P5_COPY_MISMATCH src=${TFC}/${KN} dst=${TFC}/${KN}_PREV" || return 1
  at no-later-write
  ! logged "^mutating	set soleur/${TFC}/${KP}" && [[ "$(val soleur "$TFC" "$KP")" == "$(tok OLD "$KP")" ]] && has soleur "$TFC" "${KP}_NEXT" || return 1
  at second-untouched
  [[ "$(set_lines "$TFC" "$KN")" -eq 0 && "$(val soleur "$TFC" "$KN")" == "$(tok OLD "$KN")" ]] && has soleur "$TFC" "${KN}_NEXT" || return 1
  at first-swapped
  [[ "$(val soleur "$TFC" "$KA")" == "$(tok NEW "$KA")" && "$(val soleur "$TFC" "${KA}_PREV")" == "$(tok OLD "$KA")" ]] && ! has soleur "$TFC" "${KA}_NEXT" || return 1
  at stops
  [[ "$RC" -ne 0 ]]
}
row_g2_5_order_in_window() { # <src> — every <KEY> write happens while <KEY>_PREV already holds the old value
  local k
  world g2-5 "$1"; seed_staged
  : > "$STUB_LOG"; approve swap
  at prev-old
  for k in "${KEYS[@]}"; do
    [[ "$(set_lines "$TFC" "$k")" -eq 1 ]] && logged "^mutating	set soleur/${TFC}/${k} prev=old$" || return 1
  done
  at applied
  [[ "$RC" -eq 0 ]] || return 1
  for k in "${KEYS[@]}"; do
    [[ "$(val soleur "$TFC" "$k")" == "$(tok NEW "$k")" && "$(val soleur "$TFC" "${k}_PREV")" == "$(tok OLD "$k")" ]] && ! has soleur "$TFC" "${k}_NEXT" \
      && has_line "SOLEUR_P5_SWAPPED key=${k} staging=deleted verified=digest" || return 1
  done
}
row_g2_6_empty_manifest() { # <src> — the manifest block parses to zero keys
  local b="$SB/nomanifest-$RANDOM.sh"
  at setup
  copy_with "$1" "$b" <<'PERL' || return 1
s{^# P5-MANIFEST [^\n]*\n}{}mg
PERL
  world g2-6 "$b"; seed_staged
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_P5_MANIFEST_EMPTY' && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' || return 1
  at zero-writes
  approve swap
  [[ "$(mut)" -eq 0 ]]
}
row_g2_mustpass() { # <src> — key 1 swapped in an earlier sitting, key 2 staged, key 3 not staged
  world g2-pass "$1"; seed_staged
  rmv soleur "$TFC" "${KA}_NEXT"; sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"; sv soleur "$TFC" "$KA" "$(tok NEW "$KA")"
  rmv soleur "$TFC" "${KP}_NEXT"
  cp "$STUB_D/soleur/$TFC/${KA}_PREV" "$W/audit-prev.before"
  at writes-key-2-only
  : > "$STUB_LOG"; approve swap
  [[ "$RC" -eq 0 && "$(val soleur "$TFC" "$KN")" == "$(tok NEW "$KN")" && "$(val soleur "$TFC" "${KN}_PREV")" == "$(tok OLD "$KN")" ]] && ! has soleur "$TFC" "${KN}_NEXT" || return 1
  [[ "$(grep -c '^mutating	set ' "$STUB_LOG")" -eq 2 ]] && ! logged "set soleur/${TFC}/${KA}" && ! logged "set soleur/${TFC}/${KP}" || return 1
  cmp -s "$W/audit-prev.before" "$STUB_D/soleur/$TFC/${KA}_PREV" && [[ "$(val soleur "$TFC" "$KP")" == "$(tok OLD "$KP")" ]]
}

row_g2_7_window() { # <src> <denied|unreachable> — the old token stops verifying between the _PREV copy and the <KEY> write
  local how="$2"
  world "g2-7-$how" "$1"; seed_staged; flag "old-${how}-after-prev-set"
  : > "$STUB_LOG"; approve swap
  at no-key-write
  [[ "$(set_lines "$TFC" "$KA")" -eq 0 ]] && ! logged "^mutating	set soleur/${TFC}/(${KN}|${KP})" || return 1
  at marker
  if [[ "$how" == denied ]]; then has_line "SOLEUR_P5_PREV_NOT_PINNED key=${KA}" || return 1
  else has_line "SOLEUR_P5_TOKEN_UNREACHABLE name=soleur/${TFC}/${KA}_PREV http=503" && ! grep -q '^SOLEUR_P5_PREV_NOT_PINNED ' <<<"$OUT" || return 1; fi
  at next-kept
  [[ "$RC" -ne 0 && "$(val soleur "$TFC" "${KA}_NEXT")" == "$(tok NEW "$KA")" ]] && has_line "SOLEUR_BOOTSTRAP_STAGE_FAILED stage=swap rc=1"
}
row_g2_8_key_unexpected() { # <src> — _PREV old (pinned), <KEY> an already-propagated new token, a second new token staged
  world g2-8 "$1"; seed_staged
  sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"; sv soleur "$TFC" "$KA" "$(tok NEW1 "$KA")"; sv soleur "$TFC" "${KA}_NEXT" "$(tok NEW2 "$KA")"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line "SOLEUR_P5_KEY_UNEXPECTED key=${KA}" && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 && "$(val soleur "$TFC" "$KA")" == "$(tok NEW1 "$KA")" ]]
}
row_g2_9_prev_live() { # <src> — _PREV holds a live token that is not the pin (a skipped revoke), <KEY> the pinned old one
  world g2-9 "$1"; seed_staged; sv soleur "$TFC" "${KA}_PREV" "$(tok THIRD "$KA")"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && grep -qE "^SOLEUR_P5_PREV_LIVE key=${KA} id=[0-9a-f]{8}$" <<<"$OUT" \
    && grep -qF "is not the pinned old id $(pin_of "$KA"), so copying ${KA} over it" <<<"$OUT" || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 && "$(val soleur "$TFC" "${KA}_PREV")" == "$(tok THIRD "$KA")" ]]
}
row_g2_10_next_bad() { # <src> <expired|old> — the staged value is an expired token, or the pinned old one
  local want
  world "g2-10-$2" "$1"; seed_staged
  if [[ "$2" == expired ]]; then sv soleur "$TFC" "${KA}_NEXT" "$(tok EXPIRED "$KA")"; want="verifies with status expired, not active"
  else sv soleur "$TFC" "${KA}_NEXT" "$(tok OLD "$KA")"; want="verifies the pinned OLD id $(pin_of "$KA"), so it is not a new token"; fi
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF "$want" <<<"$OUT" && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory'
}
row_g2_12_delete_unconfirmed() { # <src> — the stub's delete answers 0 and removes nothing
  world g2-12 "$1"; seed_staged; flag delete-noop
  : > "$STUB_LOG"; approve swap
  at marker
  has_line "SOLEUR_P5_DELETE_NOT_CONFIRMED name=${KA}_NEXT" && ! has_line "SOLEUR_P5_SWAPPED key=${KA} staging=deleted verified=digest" || return 1
  at stops
  [[ "$RC" -ne 0 ]] && ! logged "^mutating	set soleur/${TFC}/${KN}"
}
row_g2_13_next_not_distinct() { # <src> [write|managed] — the staged PAGERULES value is the token prd_terraform holds as
  # CF_API_TOKEN (write), or as ANOTHER managed key, CF_API_TOKEN_AUDIT (managed)
  local eq=CF_API_TOKEN
  world "g2-13-${2:-write}" "$1"; seed_staged
  if [[ "${2:-write}" == managed ]]; then sv soleur "$TFC" "${KP}_NEXT" "$(val soleur "$TFC" "$KA")"; eq="$KA"
  else sv soleur "$TFC" CF_API_TOKEN "$(tok NEW "$KP")"; fi
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && has_line "SOLEUR_P5_NEXT_NOT_DISTINCT key=${KP} equals=${eq}" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory'
}
row_g2_14_restaged_after_plan() { # <src> — the plan names each staged token's id: a re-stage before the apply is a drift
  local d k
  world g2-14 "$1"; seed_staged
  at plan-names-token
  run --stage swap; d="$(digest)"
  [[ -n "$d" ]] || return 1
  for k in "${KEYS[@]}"; do has_line "SOLEUR_BOOTSTRAP_PLAN_OP stage=swap op=copy-staged-token target=${TFC}/${k}_NEXT->${k} new_id=$(new_id_of NEW "$k") owner=user" || return 1; done
  sv soleur "$TFC" "${KP}_NEXT" "$(tok NEW2 "$KP")"
  at drift
  : > "$STUB_LOG"; apply_with_receipt swap "$d"
  [[ "$RC" -eq 75 && "$(mut)" -eq 0 ]] && has_line 'SOLEUR_BOOTSTRAP_PLAN_DRIFT stage=swap'
}
row_g2_r1_resume_after_prev() { # <src> — an earlier run stopped after AUDIT's _PREV copy: the re-run copies the staged token only
  world g2-r1 "$1"; seed_staged; sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"
  at plan
  run --stage swap
  [[ "$RC" -eq 0 ]] && grep -q "op=copy-staged-token target=${TFC}/${KA}_NEXT->${KA} " <<<"$OUT" \
    && has_line "SOLEUR_BOOTSTRAP_PLAN_OP stage=swap op=delete-staging-key target=${TFC}/${KA}_NEXT" \
    && ! grep -q "op=copy-old-token-to-revert-key target=${TFC}/${KA}->" <<<"$OUT" || return 1
  at applied
  : > "$STUB_LOG"; approve swap
  [[ "$RC" -eq 0 && "$(set_lines "$TFC" "${KA}_PREV")" -eq 0 && "$(val soleur "$TFC" "$KA")" == "$(tok NEW "$KA")" ]] \
    && ! has soleur "$TFC" "${KA}_NEXT" && has_line "SOLEUR_P5_SWAPPED key=${KA} staging=deleted verified=digest"
}
row_g2_r2_resume_after_key() { # <src> — an earlier run stopped after AUDIT's <KEY> write: the re-run only deletes the staging key
  world g2-r2 "$1"; seed_staged; sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"; sv soleur "$TFC" "$KA" "$(tok NEW "$KA")"
  at plan
  run --stage swap
  [[ "$RC" -eq 0 ]] && has_line "SOLEUR_BOOTSTRAP_PLAN_OP stage=swap op=delete-staging-key target=${TFC}/${KA}_NEXT" \
    && ! grep -qE "op=copy-[a-z-]+ target=${TFC}/${KA}(_NEXT)?->" <<<"$OUT" || return 1
  at applied
  : > "$STUB_LOG"; approve swap
  [[ "$RC" -eq 0 && "$(set_lines "$TFC" "$KA")" -eq 0 && "$(set_lines "$TFC" "${KA}_PREV")" -eq 0 ]] \
    && ! has soleur "$TFC" "${KA}_NEXT" && has_line "SOLEUR_P5_SWAPPED key=${KA} staging=deleted verified=digest"
}

# ==================================================================================================
# Guard 3 rows — holder-copies (world: seed_swapped with AUDIT's holders still old)
# ==================================================================================================
# two_holders <src> <dst> — the manifest with AUDIT holders soleur/dev_personal then soleur/dev (a rotation
# edits only the manifest block, so this is a legitimate input world).
two_holders() {
  copy_with "$1" "$2" <<'PERL'
s{(# P5-MANIFEST CF_API_TOKEN_AUDIT +\| [0-9a-f]{8} +\| soleur/prd_terraform) soleur/dev\n}{$1 soleur/dev_personal soleur/dev\n}
PERL
}
row_g3_1_last_holder_bad() { # <src> <third|absent>
  local b="$SB/twoh-$RANDOM.sh" want=other
  at setup
  two_holders "$1" "$b" || return 1
  world "g3-1-$2" "$b"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"
  if [[ "$2" == third ]]; then sv soleur dev "$KA" "$(tok THIRD "$KA")"; else rmv soleur dev "$KA"; want=absent; fi
  at refuse
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line "SOLEUR_P5_HOLDER_REFUSED key=${KA} holder=soleur/dev value=${want}" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=holder-copies need=inventory' || return 1
  at zero-writes
  approve holder-copies
  [[ "$(mut)" -eq 0 && "$(val soleur dev_personal "$KA")" == "$(tok OLD "$KA")" ]]
}
row_g3_2_second_already_new() { # <src> — first holder old, second already new: writes only the first
  local b="$SB/twoh-$RANDOM.sh"
  at setup
  two_holders "$1" "$b" || return 1
  world g3-2 "$b"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"
  : > "$STUB_LOG"; approve holder-copies
  at only-first
  [[ "$(set_lines dev "$KA")" -eq 0 && "$(set_lines dev_personal "$KA")" -eq 1 ]] || return 1
  at applied
  [[ "$RC" -eq 0 && "$(val soleur dev_personal "$KA")" == "$(tok NEW "$KA")" && "$(val soleur dev "$KA")" == "$(tok NEW "$KA")" ]] \
    && has_line "SOLEUR_P5_COPIED src=${TFC}/${KA} dst=dev_personal/${KA} verified=digest"
}
row_g3_3_before_swap() { # <src>
  world g3-3 "$1"; seed_staged
  at need-swap
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=holder-copies need=swap' && grep -qF '_NEXT is still staged' <<<"$OUT" || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 ]]
}

row_g3_r1_resume_after_first_holder() { # <src> — an earlier run wrote dev_personal, then stopped: the re-run writes dev only
  local b="$SB/twoh-$RANDOM.sh"
  at setup
  two_holders "$1" "$b" || return 1
  world g3-r1 "$b"; seed_swapped; sv soleur dev_personal "$KA" "$(tok NEW "$KA")"; sv soleur dev "$KA" "$(tok OLD "$KA")"
  : > "$STUB_LOG"; approve holder-copies
  at only-second
  [[ "$(set_lines dev_personal "$KA")" -eq 0 && "$(set_lines dev "$KA")" -eq 1 ]] || return 1
  at applied
  [[ "$RC" -eq 0 && "$(val soleur dev "$KA")" == "$(tok NEW "$KA")" ]]
}
row_g3_5_copy_mismatch() { # <src> — two old holders; the first copy does not read back equal: the second is never written
  local b="$SB/twoh-$RANDOM.sh"
  at setup
  two_holders "$1" "$b" || return 1
  world g3-5 "$b"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"; sv soleur dev "$KA" "$(tok OLD "$KA")"
  flag "corrupt.soleur.dev_personal.${KA}"
  : > "$STUB_LOG"; approve holder-copies
  at mismatch
  has_line "SOLEUR_P5_COPY_MISMATCH src=${TFC}/${KA} dst=dev_personal/${KA}" || return 1
  at no-later-write
  [[ "$(set_lines dev "$KA")" -eq 0 && "$(val soleur dev "$KA")" == "$(tok OLD "$KA")" ]] || return 1
  at stops
  [[ "$RC" -ne 0 ]] && has_line 'SOLEUR_BOOTSTRAP_STAGE_FAILED stage=holder-copies rc=1'
}
row_g3_6_source_unreadable_at_copy() { # <src> — prd_terraform <KEY> stops reading after the plan: the copy refuses before any write
  local g
  world g3-6 "$1"; seed_swapped; sv soleur dev "$KA" "$(tok OLD "$KA")"
  at setup
  : > "$STUB_LOG"; run --stage holder-copies
  g="$(grep -c "^read	get soleur/${TFC}/${KA}$" "$STUB_LOG")"
  [[ "$g" -gt 0 && "$(ops)" == 1 ]] || return 1
  printf '%s' "$((2 * g))" > "$STUB_D/.flags/get-fails-after.soleur.${TFC}.${KA}"   # the plan run and the apply's re-plan read it
  : > "$STUB_LOG"; approve holder-copies
  at no-write
  [[ "$(set_lines dev "$KA")" -eq 0 ]] || return 1
  at stops
  [[ "$RC" -ne 0 && "$(val soleur dev "$KA")" == "$(tok OLD "$KA")" ]] && has_line 'SOLEUR_BOOTSTRAP_STAGE_FAILED stage=holder-copies rc=1'
}

row_g3_4_nothing_swapped() { # <src> — nothing staged and no swap yet (<KEY> and dev still old, no _PREV): refuse need=swap
  local k
  world g3-4 "$1"
  for k in "${KEYS[@]}"; do sv soleur "$TFC" "$k" "$(tok OLD "$k")"; done
  sv soleur dev "$KA" "$(tok OLD "$KA")"
  at need-swap
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=holder-copies need=swap' && ! grep -q '^SOLEUR_P5_HOLDER_COPY ' <<<"$OUT" || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 ]]
}
row_i1_reference_unreadable() { # <src> — AUDIT_PREV verifies the pin, then its one value read fails: census-blind, never old_hits=0
  world i-1 "$1"; seed_swapped
  printf '4' > "$STUB_D/.flags/get-fail-nth.soleur.${TFC}.${KA}_PREV"   # reads 1-3: the shape pass and both verify endpoints
  at verdict
  run --stage inventory
  [[ "$RC" -ne 0 ]] && has_line "SOLEUR_P5_REFERENCE key=${KA} source=PREV" && has_line "SOLEUR_P5_CENSUS_BLIND key=${KA} source=PREV" \
    && ! grep -q "^SOLEUR_P5_CENSUS key=${KA} " <<<"$OUT"
}

# ==================================================================================================
# Scenario rows
# ==================================================================================================
row_s1_happy_path() { # <src>
  local k st
  world s1 "$1"; seed_staged
  at inventory-pre
  run --stage inventory
  [[ "$RC" -eq 0 ]] || return 1
  for k in "${KEYS[@]}"; do has_line "SOLEUR_P5_STAGED key=${k} next=present prev=absent" && has_line "SOLEUR_P5_REFERENCE key=${k} source=KEY" || return 1; done
  at swap
  approve swap
  [[ "$RC" -eq 0 && "$(grep -c '^SOLEUR_P5_SWAPPED ' <<<"$OUT")" -eq 3 ]] || return 1
  at holder-copies
  approve holder-copies
  [[ "$RC" -eq 0 && "$(val soleur dev "$KA")" == "$(tok NEW "$KA")" ]] || return 1
  at verify
  run --stage verify
  [[ "$RC" -eq 0 ]] && has_line 'SOLEUR_P5_VERIFY verdict=ok' && has_line "SOLEUR_P5_GRAPHQL key=${KN} zone_tag=match errors=0" || return 1
  for k in "${KEYS[@]}"; do vok "$k" && ready "$k" || return 1; done
  ! grep -qE '"count"|synth-actor|192\.0\.2\.7' <<<"$OUT" || return 1
  at revoke
  flag revoked-old
  run --stage verify   # the same-sitting read-back after the revoke (CTO D6): revoked, never a failure or a REVOKE_READY
  [[ "$RC" -eq 0 ]] && has_line 'SOLEUR_P5_VERIFY verdict=ok' || return 1
  for k in "${KEYS[@]}"; do
    has_line "SOLEUR_P5_VERIFY key=${k} verdict=revoked" && has_line "SOLEUR_P5_PREV key=${k} state=denied" && noready "$k" \
      && has_line "SOLEUR_P5_HOLDER project=soleur config=${TFC} key=${k}_PREV value=revoked" || return 1
  done
  for k in "${KEYS[@]}"; do rmv soleur "$TFC" "${k}_PREV"; done    # the revoke recipe's step-4 key delete (a hold)
  run --stage inventory
  [[ "$RC" -eq 0 ]] || return 1
  for k in "${KEYS[@]}"; do
    has_line "SOLEUR_P5_REFERENCE key=${k} source=none" && has_line "SOLEUR_P5_STAGED key=${k} next=absent prev=absent" \
      && has_line "SOLEUR_P5_PREV key=${k} state=absent" \
      && has_line "SOLEUR_P5_HOLDER project=soleur config=${TFC} key=${k}_PREV value=absent" || return 1
  done
  at satisfied
  for st in swap holder-copies; do
    : > "$STUB_LOG"; run --stage "$st"
    [[ "$RC" -eq 0 && "$(ops)" == 0 && "$(mut)" -eq 0 ]] || return 1
  done
  at no-github
  [[ ! -e "$STUB_D/.gh-called" ]]
}
row_s2_account_owned() { # <src> — /user/tokens/verify refuses, the account endpoint answers active
  world s2 "$1"; seed_swapped; sv soleur "$TFC" "$KA" "$(tok ACCT "$KA")"; sv soleur dev "$KA" "$(tok ACCT "$KA")"
  at verdict
  : > "$STUB_LOG"; run --stage verify
  [[ "$RC" -eq 0 ]] && vok "$KA" && ready "$KA" account && grep -qE "^SOLEUR_P5_KEY key=${KA} id=[0-9a-f]{8} status=active owner=account$" <<<"$OUT"
}
row_s3_unreachable() { # <src> — 429 on verify reads in verify, 503 in the swap plan: no verdict either way
  world s3a "$1"; seed_swapped; flag curl-429
  at verify-unreachable
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_TOKEN_UNREACHABLE name=soleur/${TFC}/${KA} http=429" && vfail_is "$KA" unreachable \
    && ! grep -q '^SOLEUR_P5_REVOKE_READY ' <<<"$OUT" || return 1
  world s3b "$1"; seed_staged; flag curl-503
  at swap-unreachable
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && has_line "SOLEUR_P5_TOKEN_UNREACHABLE name=soleur/${TFC}/${KA}_NEXT http=503" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory'
}
row_s4_no_receipt() { # <src> — an apply without a receipt exits 75 and writes nothing
  local d
  world s4a "$1"; seed_staged
  at swap-75
  run --stage swap; d="$(digest)"; [[ -n "$d" && "$(ops)" -gt 0 ]] || return 1
  : > "$STUB_LOG"; run --stage swap --apply --plan-digest "$d"
  [[ "$RC" -eq 75 && "$(mut)" -eq 0 ]] && grep -q '^SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=swap ' <<<"$OUT" || return 1
  world s4b "$1"; seed_swapped; sv soleur dev "$KA" "$(tok OLD "$KA")"
  at holder-copies-75
  run --stage holder-copies; d="$(digest)"; [[ -n "$d" && "$(ops)" == 1 ]] || return 1
  : > "$STUB_LOG"; run --stage holder-copies --apply --plan-digest "$d"
  [[ "$RC" -eq 75 && "$(mut)" -eq 0 ]] && grep -q '^SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=holder-copies ' <<<"$OUT"
}
row_s5_malformed_next() { # <src> <quote|newline> — the LAST key's staged value is malformed
  world "s5-$2" "$1"; seed_staged
  if [[ "$2" == quote ]]; then sv soleur "$TFC" "${KP}_NEXT" 'SYNTH-BAD"QUOTE-SENTINEL'
  else printf '%s\n%s' 'SYNTH-BAD-LINE1' 'url = "https://injected.invalid/"' > "$STUB_D/soleur/$TFC/${KP}_NEXT"; fi
  : > "$STUB_LOG"
  at refuse
  run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line "SOLEUR_P5_TOKEN_MALFORMED name=soleur/${TFC}/${KP}_NEXT" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' || return 1
  at no-curl
  ! logged 'curl' || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 ]]
}
row_s6_analytics_api_error() { # <src> — the zone-tag query passes and analytics-health says api-error: still ok
  world s6 "$1"; seed_swapped; flag analytics-api-error
  at verdict
  run --stage verify
  [[ "$RC" -eq 0 ]] && vok "$KN" && ready "$KN" && has_line "SOLEUR_P5_GRAPHQL key=${KN} zone_tag=match errors=0" \
    && grep -qE "^SOLEUR_P5_CONSUMER key=${KN} sub=analytics-health gating=no rc=14 line=cloudflare-readonly: analytics-health unverified - api-error \(graphql: " <<<"$OUT"
}
row_s7_graphql() { # <src> <mismatch|errors> — no new zone tag, or the new zone tag with an error
  local zt=mismatch; [[ "$2" == errors ]] && zt=match
  world "s7-$2" "$1"; seed_swapped; flag "graphql-$2"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KN" consumer-read && noready "$KN" && has_line "SOLEUR_P5_GRAPHQL key=${KN} zone_tag=${zt} errors=1" && vok "$KA"
}
row_s8_old_target_ids() { # <src> <zone|account> — prd_terraform still names the old zone, or an account that is not the new one
  local k
  world "s8-$2" "$1"; seed_swapped
  if [[ "$2" == zone ]]; then sv soleur "$TFC" CF_ZONE_ID "$OZ"; else sv soleur "$TFC" CF_ACCOUNT_ID "$OA"; fi
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" target-ids-not-new && noready "$k" || return 1; done
  ! logged 'consumer '
}

row_s9_consumer_fails() { # <src> — AUDIT's own consumer read answers unverified: only AUDIT fails
  world s9 "$1"; seed_swapped; flag consumer-fail.change-history
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" consumer-read && noready "$KA" && vok "$KN" && vok "$KP" \
    && has_line "SOLEUR_P5_CONSUMER key=${KA} sub=change-history gating=yes rc=11 line=cloudflare-readonly: change-history unverified - token-lacks-scope"
}
row_s3c_403_html() { # <src> — a 403 with an HTML body is no verdict (only a JSON success:false is a denial)
  world s3c "$1"; seed_swapped; flag curl-403-html
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_TOKEN_UNREACHABLE name=soleur/${TFC}/${KA} http=403" && vfail_is "$KA" unreachable && ! grep -q '^SOLEUR_P5_REVOKE_READY ' <<<"$OUT"
}

# The refusal lists, one member per E1 row (security N6, testdesign S15). Each variable's value is chosen so that
# it does not also mislead the template's .env ignore probe (which runs first and would refuse with its own marker):
# the row isolates the class refusal. E1_FUNCS are exported shell functions that delegate to the real command, so
# a run that ignores them would otherwise succeed.
E1_VARS=(GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_OBJECT_DIRECTORY GIT_COMMON_DIR GIT_NAMESPACE
         GIT_ALTERNATE_OBJECT_DIRECTORIES GIT_CONFIG_GLOBAL GIT_CONFIG_SYSTEM GIT_CONFIG_COUNT GIT_CONFIG_PARAMETERS
         GIT_EXEC_PATH GIT_SYNTH_UNLISTED BASH_ENV ENV DOPPLER_API_HOST
         DOPPLER_CONFIG_DIR HTTPS_PROXY https_proxy HTTP_PROXY http_proxy ALL_PROXY all_proxy SSL_CERT_FILE SSL_CERT_DIR)
E1_NET=(DOPPLER_CONFIG_DIR HTTPS_PROXY https_proxy HTTP_PROXY http_proxy ALL_PROXY all_proxy SSL_CERT_FILE SSL_CERT_DIR)
E1_FUNCS=(doppler curl git jq sed synth_unlisted_fn)
row_e1_env_refused() { # <src> <var|function> <name> — an inherited variable or exported function is refused by class
  local want ex
  world "e1-$2-$3" "$1"; seed_swapped
  if [[ "$2" == function ]]; then
    want="function:$3"
    if [[ "$3" == synth_unlisted_fn ]]; then ex="BASH_FUNC_$3%%=() { :; }"; else ex="BASH_FUNC_$3%%=() { command $3 \"\$@\"; }"; fi
  else
    want="$3"
    case "$3" in
      GIT_CONFIG_GLOBAL|GIT_CONFIG_SYSTEM|BASH_ENV|ENV) ex="$3=/dev/null" ;;
      GIT_CONFIG_COUNT) ex="$3=0" ;;
      GIT_CONFIG_PARAMETERS) ex="$3='synth.unlisted'='1'" ;;
      GIT_NAMESPACE|GIT_SYNTH_UNLISTED) ex="$3=synth" ;;
      DOPPLER_API_HOST) ex="$3=https://doppler.invalid" ;;
      *) ex="$3=$W/no-such-git-location" ;;
    esac
  fi
  at refuse
  : > "$STUB_LOG"; run_with "$ex" -- --stage verify
  [[ "$RC" -eq 64 && ! -s "$STUB_LOG" ]] && has_line "SOLEUR_P5_ENV_REFUSED name=${want}"
}
row_e1_env_inert() { # <src> — the five GIT_* variables git never consults for these reads do not refuse (harnesses set GIT_EDITOR)
  local k
  world e1-inert "$1"; seed_swapped
  at verdict
  run_with GIT_EDITOR=true GIT_SEQUENCE_EDITOR=true GIT_PAGER=cat GIT_TERMINAL_PROMPT=0 "GIT_CEILING_DIRECTORIES=$SB" -- --stage verify
  [[ "$RC" -eq 0 ]] && ! grep -q '^SOLEUR_P5_ENV_REFUSED ' <<<"$OUT" || return 1
  for k in "${KEYS[@]}"; do ready "$k" || return 1; done
}
row_t1_dirty_file() { # <src> <tool|inventory> — an UNCOMMITTED edit to a tracked file the bootstrap runs or reads
  world "t1-$2" "$1"; seed_swapped
  at verdict
  if [[ "$2" == tool || "$2" == filter ]]; then
    if [[ "$2" == filter ]]; then
      # A clean filter that strips the edit makes a FILTERED hash-object equal the HEAD blob: only the raw
      # bytes (--no-filters) show the edit. The filter and its attribute live in the fixture's .git, untracked.
      mkdir -p "$W/repo/.git/info"
      printf '[filter "p5strip"]\n\tclean = sed -e /p5-uncommitted-edit/d\n' >> "$W/repo/.git/config"
      printf 'plugins/soleur/scripts/cloudflare-readonly.sh filter=p5strip\n' > "$W/repo/.git/info/attributes"
      printf '# p5-uncommitted-edit\n' >> "$W/repo/plugins/soleur/scripts/cloudflare-readonly.sh"
    else
      printf '\n# an uncommitted edit\n' >> "$W/repo/plugins/soleur/scripts/cloudflare-readonly.sh"
    fi
    : > "$STUB_LOG"; run --stage verify
    [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_UNTRUSTED_FILE path=plugins/soleur/scripts/cloudflare-readonly.sh" && ! logged '^read	consumer ' \
      && vfail_is "$KA" consumer-read && noready "$KA" && noready "$KP"
  else
    printf 'an_uncommitted_config\n' >> "$W/repo/$INV_REL"
    : > "$STUB_LOG"; run --stage verify
    [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_UNTRUSTED_FILE path=${INV_REL}" && has_line "SOLEUR_P5_FLOOR_MISSING name=inventory:${INV_REL}" \
      && vfail_is "$KA" census-floor && noready "$KA"
  fi
}
row_m1_manifest_invalid() { # <src> <variant> — one manifest line the parser must refuse (with its file line), never skip
  local b="$SB/mf-$2-$RANDOM.sh" want=shape ln prog
  case "$2" in
    tab)       prog='s{^# P5-MANIFEST (CF_API_TOKEN_ANALYTICS_READ)}{# P5-MANIFEST\t$1}m' ;;
    indent)    prog='s{^(# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ)}{ $1}m' ;;
    nospace)   prog='s{^# P5-MANIFEST (CF_API_TOKEN_ANALYTICS_READ)}{#P5-MANIFEST $1}m' ;;
    fourth)    prog='s{^(# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ[^\n]*)$}{$1 | soleur/dev}m' ;;
    prefix)    prog='s{^(# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ +\| [0-9a-f]{8} +\| )soleur/prd_terraform$}{${1}soleur/prd_terraform_x}m' ;;
    dupkey)    prog="s{^# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ [^\\n]*\$}{# P5-MANIFEST ${KA} | $(pin_of "$KA") | soleur/prd_terraform}m"; want=duplicate-key ;;
    suffix)    prog='s{^(# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ)( +\|)}{${1}_PREV$2}m'; want=suffix ;;
    dupholder) prog='s{^(# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ[^\n]*)$}{$1 soleur/dev soleur/dev}m'; want=duplicate-holder ;;
  esac
  ln="$(grep -n '^# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ ' "$1" | cut -d: -f1)"
  at setup
  [[ -n "$ln" ]] && copy_with "$1" "$b" <<<"$prog" || return 1
  world "m1-$2" "$b"; seed_staged
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -ne 0 && -z "$(digest)" && "$(mut)" -eq 0 ]] && has_line "SOLEUR_P5_MANIFEST_INVALID line=${ln} reason=${want}"
}
row_f1_floor_line() { # <src> <removed|duplicated|malformed> — the `# P5-PROJECT-FLOOR` line is not exactly one well-formed line
  local k b="$SB/fl-$2-$RANDOM.sh" prog
  case "$2" in
    removed)    prog='s{^# P5-PROJECT-FLOOR [^\n]*\n}{}m' ;;
    duplicated) prog='s{^(# P5-PROJECT-FLOOR [^\n]*\n)}{$1$1}m' ;;
    malformed)  prog='s{^(# P5-PROJECT-FLOOR [^\n]*)$}{$1 not/a-project}m' ;;
  esac
  at setup
  copy_with "$1" "$b" <<<"$prog" || return 1
  world "f1-$2" "$b"; seed_swapped
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line 'SOLEUR_P5_FLOOR_MISSING name=project-floor-line' || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-floor && noready "$k" || return 1; done
}

# ==================================================================================================
# The _PREV state (CTO D6): one row per state, printed by inventory AND verify
# ==================================================================================================
DEAD_TOKEN_KIND=DEAD   # a well-formed value the curl stub denies at both endpoints (no -SENTINEL suffix): a revoked token
dead_tok() { printf 'SYNTH-%s-%s' "$DEAD_TOKEN_KIND" "$1"; }
row_p1_prev_state() { # <src> <pinned|denied|other|malformed|unreadable|unreachable|absent>
  local want="SOLEUR_P5_PREV key=${KA} state=$2" st
  world "p1-$2" "$1"
  case "$2" in
    absent)      seed_staged ;;
    pinned)      seed_swapped; want="${want} id=$(pin_of "$KA") owner=user" ;;
    denied)      seed_swapped; sv soleur "$TFC" "${KA}_PREV" "$(dead_tok "$KA")" ;;
    other)       seed_swapped; sv soleur "$TFC" "${KA}_PREV" "$(tok THIRD "$KA")"; want="${want} id=$(new_id_of THIRD "$KA") owner=user" ;;
    malformed)   seed_swapped; sv soleur "$TFC" "${KA}_PREV" 'SYNTH-BAD"QUOTE-SENTINEL' ;;
    unreadable)  seed_swapped; flag "get-fails.soleur.${TFC}.${KA}_PREV" ;;
    unreachable) seed_swapped; flag curl-503 ;;
  esac
  for st in inventory verify; do
    at "$st"
    run --stage "$st"
    has_line "$want" && [[ "$(grep -c "^SOLEUR_P5_PREV key=${KA} " <<<"$OUT")" -eq 1 ]] || return 1
  done
}
row_v1_revoked() { # <src> — AUDIT's old token is revoked (its _PREV denied at both endpoints); the other two keys are not yet
  world v1 "$1"; seed_swapped; sv soleur "$TFC" "${KA}_PREV" "$(dead_tok "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 0 ]] && has_line "SOLEUR_P5_VERIFY key=${KA} verdict=revoked" && noready "$KA" && has_line 'SOLEUR_P5_VERIFY verdict=ok' \
    && has_line "SOLEUR_P5_PREV key=${KA} state=denied" && has_line "SOLEUR_P5_REFERENCE key=${KA} source=none" \
    && ! grep -q "^SOLEUR_P5_VERIFY key=${KA} verdict=fail" <<<"$OUT" || return 1
  at others
  vok "$KN" && ready "$KN" && vok "$KP" && ready "$KP" || return 1
  at census-row
  has_line "SOLEUR_P5_HOLDER project=soleur config=${TFC} key=${KA}_PREV value=revoked" || return 1
  at inventory-row
  run --stage inventory
  [[ "$RC" -eq 0 ]] && has_line "SOLEUR_P5_HOLDER project=soleur config=${TFC} key=${KA}_PREV value=revoked" || return 1
  at checks-still-run
  sv soleur dev "$KA" "$(tok THIRD "$KA")"
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" holder-not-new && ! grep -q "^SOLEUR_P5_VERIFY key=${KA} verdict=revoked" <<<"$OUT"
}

# ==================================================================================================
# Swap and the _PREV it may overwrite (dataint N3): only absent, denied, or the pinned old token
# ==================================================================================================
row_g2_15_prev_refused() { # <src> <unreadable|malformed|expired> — _PREV cannot be read, is not a token, or is another token
  local want st
  # Only AUDIT is staged: another staged key's distinctness pass reads AUDIT_PREV too, and would refuse an
  # unreadable one first, so the row isolates AUDIT's own _PREV check.
  world "g2-15-$2" "$1"; seed_staged; rmv soleur "$TFC" "${KN}_NEXT"; rmv soleur "$TFC" "${KP}_NEXT"
  case "$2" in
    unreadable) sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"; flag "get-fails.soleur.${TFC}.${KA}_PREV"; st=unreadable
                want="${TFC}/${KA}_PREV is listed but could not be read, so nothing is decided. Run this stage again." ;;
    malformed)  sv soleur "$TFC" "${KA}_PREV" 'SYNTH-BAD"QUOTE-SENTINEL'; st=malformed
                want="${TFC}/${KA}_PREV holds a value that is not a well-formed token, so nothing proves which token a copy over it would lose." ;;
    expired)    sv soleur "$TFC" "${KA}_PREV" "$(tok EXPIRED "$KA")"; st="other id=$(new_id_of EXPIRED "$KA") owner=user"
                want="${TFC}/${KA}_PREV holds a token (id $(new_id_of EXPIRED "$KA"), status expired) that is not the pinned old id $(pin_of "$KA"), so copying ${KA} over it" ;;
  esac
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && has_line "SOLEUR_P5_PREV key=${KA} state=${st}" && grep -qF "$want" <<<"$OUT" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' || return 1
  at prev-kept
  [[ "$(val soleur "$TFC" "${KA}_NEXT")" == "$(tok NEW "$KA")" ]] && has soleur "$TFC" "${KA}_PREV"
}
row_g2_16_denied_prev_overwritten() { # <src> — the next rotation: _PREV holds the earlier, revoked token, <KEY> the pinned one
  world g2-16 "$1"; seed_staged; sv soleur "$TFC" "${KA}_PREV" "$(dead_tok "$KA")"
  at plan
  run --stage swap
  [[ "$RC" -eq 0 ]] && has_line "SOLEUR_P5_PREV key=${KA} state=denied" \
    && has_line "SOLEUR_BOOTSTRAP_PLAN_OP stage=swap op=copy-old-token-to-revert-key target=${TFC}/${KA}->${KA}_PREV" || return 1
  at applied
  : > "$STUB_LOG"; approve swap
  [[ "$RC" -eq 0 && "$(val soleur "$TFC" "${KA}_PREV")" == "$(tok OLD "$KA")" && "$(val soleur "$TFC" "$KA")" == "$(tok NEW "$KA")" ]]
}
row_g2_17_key_unreadable_on_resume() { # <src> — _PREV pinned (an interrupted swap) and the value read of <KEY> fails
  world g2-17 "$1"; seed_staged; sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"; flag "get-fails.soleur.${TFC}.${KA}"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && has_line "SOLEUR_P5_UNREADABLE project=soleur config=${TFC} name=${KA}" \
    && grep -qF "${TFC}/${KA} could not be read (or is empty), so nothing proves which value ${TFC}/${KA} holds. Run this stage again." <<<"$OUT" \
    && ! grep -q '^SOLEUR_P5_KEY_UNEXPECTED ' <<<"$OUT"
}

# ==================================================================================================
# The rows on the real script (full mode)
# ==================================================================================================
if [[ "$MODE" == full ]]; then
  echo "== static contract =="
  r=1; [[ "$(sed -n 2p "$SCRIPT_SRC")" == '# SOLEUR-GENERATED-OPERATOR-SCRIPT v2' ]] && r=0
  check "line 2 is the v2 generated-script header" "$r"
  OUT="$(bash "$SCRIPT_SRC" --list 2>&1)"; RC=$?
  r=1; [[ "$RC" -eq 0 && "$OUT" == "$(printf '%s\n' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=inventory class=read' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=swap class=write' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=holder-copies class=write' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=verify class=read')" ]] && r=0
  check "--list prints the four stages in table order with their class (AC2)" "$r"
  [[ "$(grep -c '^# P5-MANIFEST ' "$SCRIPT_SRC")" -eq 3 ]] \
    && grep -qE '^# P5-MANIFEST CF_API_TOKEN_AUDIT +\| dd6d1427 +\| soleur/prd_terraform soleur/dev$' "$SCRIPT_SRC" \
    && grep -qE '^# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ +\| 5993721f +\| soleur/prd_terraform$' "$SCRIPT_SRC" \
    && grep -qE '^# P5-MANIFEST CF_API_TOKEN_PAGERULES_READ +\| 86aa993e +\| soleur/prd_terraform$' "$SCRIPT_SRC"
  check "the manifest block holds the three keys, their pinned ids and holders (plan Phase 3)" $?
  [[ "$(grep -c '^# P5-PROJECT-FLOOR ' "$SCRIPT_SRC")" -eq 1 ]] \
    && grep -qxF '# P5-PROJECT-FLOOR soleur soleur-infra-privileged soleur-inngest soleur-registry soleur-deploy-channel soleur-infra-app soleur-github-app soleur-git-data-root example-project' "$SCRIPT_SRC"
  check "the census floor line names exactly the nine projects measured 2026-11-27 (CTO D2), once" $?
  r=1; awk -F'|' '$1 == "# SOLEUR-STAGE swap" { print NF; print $4 }' "$SCRIPT_SRC" > "$SB/swap-rollback.txt"
  [[ "$(sed -n 1p "$SB/swap-rollback.txt")" == 4 \
     && "$(sed -n 2p "$SB/swap-rollback.txt")" == "A partial swap has no rollback: re-run swap, which resumes every partial state. A completed swap whose new token is bad: first undo holder-copies, then the runbook's guarded _PREV-over-KEY copy (section 12), then retire the bad token." ]] \
    && ! grep -qF 'back to KEY_NEXT' "$SCRIPT_SRC" && r=0
  check "the swap rollback is the CTO D8 text exactly (no |), and the withdrawn 'back to KEY_NEXT' recipe is gone from the script" "$r"
  ! grep -nE '(^|[^*])feat-one-shot-12931-phase5-token-remint/decision-challenges\.md' "$SCRIPT_SRC" \
    && grep -qF '`knowledge-base/project/specs/**/*feat-one-shot-12931-phase5-token-remint/decision-challenges.md`' "$SCRIPT_SRC" \
    && grep -qF 'In THIS file a rotation edits only the MANIFEST block' "$SCRIPT_SRC" && grep -qF '(runbook section 11)' "$SCRIPT_SRC" \
    && ! grep -qF 'a rotation edits only the MANIFEST block below.' "$SCRIPT_SRC"
  check "the header cites the rulings by glob (never the live spec path) and names what else a rotation regenerates" $?
  # The template's contract region: everything between `set -euo pipefail` and the STAGES banner is the template's,
  # but the stage-table lines, the baked library path, the shellcheck source path and the SLUG line.
  _ttop() {
    awk '/^# STAGES/{exit} f{print} /^set -euo pipefail$/{f=1}' "$1" | sed -e '/^# SOLEUR-STAGE /d' -e '/^SLUG=/d' \
      -e 's/^SOLEUR_OP_LIB_BAKED=.*/SOLEUR_OP_LIB_BAKED=<baked>/' -e 's/^# shellcheck source=[^ ]* /# shellcheck source=<path> /' \
      -e 's/ Replace the two examples\.$//'
  }
  [[ -n "$(_ttop "$SCRIPT_SRC")" ]] && cmp -s <(_ttop "${REPO_ROOT}/plugins/soleur/skills/operator-bootstrap/template.sh") <(_ttop "$SCRIPT_SRC") \
    && [[ "$(grep -n 'SOLEUR_P5_ENV_REFUSED' "$SCRIPT_SRC" | head -1 | cut -d: -f1)" -gt "$(grep -n '^# STAGES' "$SCRIPT_SRC" | cut -d: -f1)" ]]
  check "above the STAGES banner the script is the template but the stage table, baked path, shellcheck path and SLUG (the env refusal and manifest sit below)" $?
  _treg() { awk '/^# --- the credentials file must be ignored by git/{on=1} on{print} /^trap on_exit EXIT$/{exit}' "$1"; }
  [[ -n "$(_treg "$SCRIPT_SRC")" ]] && cmp -s <(_treg "${REPO_ROOT}/plugins/soleur/skills/operator-bootstrap/template.sh") <(_treg "$SCRIPT_SRC")
  check "the .env probe through the on_exit trap is byte-identical to the operator-bootstrap template (comments included)" $?
  ! grep -nE 'soleur-infra-privileged' <(grep -v '^#' "$SCRIPT_SRC" | grep -vE '^[[:space:]]*#')
  check "no executable line names soleur-infra-privileged (no stage writes there)" $?
  # The REAL consumer wrapper's contract, read from its code (comments stripped): the verdict lines the
  # bootstrap parses, the three subcommands and the key each binds, the environment allowlist the
  # bootstrap's --only-secrets names mirror, and the source guard. A change to any of these reds here.
  RO_CODE="$(grep -vE '^[[:space:]]*#' "${REPO_ROOT}/plugins/soleur/scripts/cloudflare-readonly.sh")"
  r=0
  while IFS= read -r _pat; do grep -qF -- "$_pat" <<<"$RO_CODE" || { r=1; printf '    contract line missing from cloudflare-readonly.sh: %s\n' "$_pat"; }; done <<'CONTRACT'
printf 'cloudflare-readonly: %s ok\n%s\n' "$SUB"
printf 'cloudflare-readonly: %s unverified - %s\n' "$SUB" "$1"
pagerules-ssl) TOKVAR=CF_API_TOKEN_PAGERULES_READ; load_credential zone;
change-history) TOKVAR=CF_API_TOKEN_AUDIT; load_credential account;
analytics-health) need_hours "$@"; TOKVAR=CF_API_TOKEN_ANALYTICS_READ; load_credential zone;
DOPPLER_PROJECT | DOPPLER_CONFIG | CF_ZONE_ID | CF_ACCOUNT_ID
if [ "${DOPPLER_PROJECT:-}" != soleur ] || [ "${DOPPLER_CONFIG:-}" != prd_terraform ]; then
CONTRACT
  for _s in pagerules-ssl change-history analytics-health; do grep -qE "^SUBCOMMANDS=\\(([^)]* )?${_s}( [^)]*)?\\)$" <<<"$RO_CODE" || r=1; done
  check "the real cloudflare-readonly.sh still has the verdict lines, subcommands, key bindings, allowlist and source guard the bootstrap relies on" "$r"
  world static
  run --stage no-such-stage
  [[ "$RC" -eq 64 ]] && has_line 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=no-such-stage'
  check "an undeclared stage exits 64 UNKNOWN_STAGE" $?
  run
  [[ "$RC" -eq 64 ]] && has_line 'SOLEUR_BOOTSTRAP_STAGE_REQUIRED'
  check "no --stage exits 64 STAGE_REQUIRED (no run-all mode)" $?
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" bash -x "$S" --stage inventory </dev/null 2>&1)"; RC=$?
  [[ "$RC" -eq 78 ]] && grep -qF '[FATAL] refusing to run under xtrace' <<<"$OUT"
  check "a run under xtrace is refused with exit 78" $?

  echo "== Guard 1: verify's census and REVOKE_READY =="
  row_g1_1_floor "$SCRIPT_SRC"; check "G1-1 doppler projects answers []: fail reason=census-floor, no REVOKE_READY" $?
  row_g1_2_blind "$SCRIPT_SRC"; check "G1-2 a census that cannot see the old value: fail reason=census-blind" $?
  row_g1_3_second_member "$SCRIPT_SRC"; check "G1-3 dev new, dev_personal old: fail naming soleur/dev_personal" $?
  row_g1_4_unlisted_project "$SCRIPT_SRC"; check "G1-4 other/ci (in no manifest) holds the old value: fail naming other/ci; holder-copies plans nothing there" $?
  row_g1_5_expired "$SCRIPT_SRC"; check "G1-5 <KEY> verifies a new id with status=expired: fail reason=key-not-active" $?
  row_g1_6_prev_new "$SCRIPT_SRC"; check "G1-6 <KEY>_PREV holds the new value: source=none, no REVOKE_READY" $?
  row_g1_7_get_error "$SCRIPT_SRC"; check "G1-7 a failed get of a listed name: UNREADABLE, fail reason=census-unreadable" $?
  row_g1_mustpass "$SCRIPT_SRC"; check "G1 must-PASS: other/ci new and soleur/prd absent: ok plus REVOKE_READY for all three keys, each key's own consumer" $?
  row_g1_8_hidden_holder "$SCRIPT_SRC"; check "G1-8 a manifest holder config the listing hides: FLOOR_MISSING naming it, census-floor" $?
  row_g1_9_names_unreadable "$SCRIPT_SRC"; check "G1-9 a config whose names listing fails: UNREADABLE, census-unreadable" $?
  row_g1_10_configs_unreadable "$SCRIPT_SRC"; check "G1-10 a project whose configs listing fails: UNREADABLE config=-, census-unreadable" $?
  row_g1_11_next_staged "$SCRIPT_SRC"; check "G1-11 a _NEXT still staged at verify: fail reason=next-staged" $?
  row_g1_12_names_array "$SCRIPT_SRC"; check "G1-12 a names listing answered as an array: UNREADABLE, census-unreadable" $?
  row_g1_13_floor "$SCRIPT_SRC" project; check "G1-13 the listing drops soleur-infra-privileged: FLOOR_MISSING, census-floor, no REVOKE_READY" $?
  row_g1_13_floor "$SCRIPT_SRC" config; check "G1-13 the listing drops soleur/dev_personal: FLOOR_MISSING, census-floor, no REVOKE_READY" $?
  row_g1_14_holder_not_new "$SCRIPT_SRC" absent; check "G1-14 the manifest holder dev lacks the key: HOLDER_NOT_NEW, fail reason=holder-not-new" $?
  row_g1_14_holder_not_new "$SCRIPT_SRC" other; check "G1-14 the manifest holder dev holds a third value: HOLDER_NOT_NEW, fail reason=holder-not-new" $?
  row_g1_15_prev_expired "$SCRIPT_SRC"; check "G1-15 _PREV verifies the pin with status expired: fail reason=prev-not-active" $?

  echo "== Guard 2: swap =="
  row_g2_1_key_not_pinned "$SCRIPT_SRC"; check "G2-1 <KEY> not the pinned id, no _PREV: refuse with the named sentence, zero writes" $?
  row_g2_2_prev_by_name "$SCRIPT_SRC"; check "G2-2 a _PREV holding a non-pinned value: refuse (value, not name), zero writes" $?
  row_g2_3_prev_copy_mismatch "$SCRIPT_SRC"; check "G2-3 the _PREV copy does not read back equal: COPY_MISMATCH, no <KEY> write, _NEXT kept" $?
  row_g2_4_second_key_fails "$SCRIPT_SRC"; check "G2-4 key 2's _PREV copy fails: key 2 and key 3 untouched, their _NEXT kept" $?
  row_g2_5_order_in_window "$SCRIPT_SRC"; check "G2-5 every set <KEY> is logged prev=old (the order observed inside the write window)" $?
  row_g2_6_empty_manifest "$SCRIPT_SRC"; check "G2-6 a manifest that parses to zero keys: MANIFEST_EMPTY refusal, zero writes" $?
  row_g2_mustpass "$SCRIPT_SRC"; check "G2 must-PASS: key 1 swapped earlier, key 2 staged: writes key 2 only, key 1's _PREV unchanged" $?
  row_g2_7_window "$SCRIPT_SRC" denied; check "G2-7 the old token is denied after the _PREV copy: PREV_NOT_PINNED, no <KEY> write, _NEXT kept" $?
  row_g2_7_window "$SCRIPT_SRC" unreachable; check "G2-7 the _PREV re-check gets no verdict: TOKEN_UNREACHABLE (never PREV_NOT_PINNED), no <KEY> write" $?
  row_g2_8_key_unexpected "$SCRIPT_SRC"; check "G2-8 _PREV pinned but <KEY> holds a third (propagated) token: KEY_UNEXPECTED refusal, zero writes" $?
  row_g2_9_prev_live "$SCRIPT_SRC"; check "G2-9 a live non-pinned _PREV (a skipped revoke): PREV_LIVE refusal, _PREV kept" $?
  row_g2_10_next_bad "$SCRIPT_SRC" expired; check "G2-10 a staged _NEXT with status expired: refused, zero writes" $?
  row_g2_10_next_bad "$SCRIPT_SRC" old; check "G2-10 the pinned old token staged as _NEXT: refused, zero writes" $?
  row_g2_12_delete_unconfirmed "$SCRIPT_SRC"; check "G2-12 a delete the listing does not confirm: DELETE_NOT_CONFIRMED, no SWAPPED, stage stops" $?
  row_g2_13_next_not_distinct "$SCRIPT_SRC" write; check "G2-13 a staged _NEXT equal to prd_terraform CF_API_TOKEN: NEXT_NOT_DISTINCT refusal, zero writes" $?
  row_g2_13_next_not_distinct "$SCRIPT_SRC" managed; check "G2-13 a staged _NEXT equal to another managed key (CF_API_TOKEN_AUDIT): NEXT_NOT_DISTINCT refusal, zero writes" $?
  row_g2_14_restaged_after_plan "$SCRIPT_SRC"; check "G2-14 the plan names the exact new_id and owner; a _NEXT re-staged after the plan is PLAN_DRIFT 75, zero writes" $?
  row_g2_15_prev_refused "$SCRIPT_SRC" unreadable; check "G2-15 a _PREV whose read fails (rc 4): state=unreadable, re-run refusal, zero writes" $?
  row_g2_15_prev_refused "$SCRIPT_SRC" malformed; check "G2-15 a malformed _PREV (rc 2): state=malformed, refusal, zero writes" $?
  row_g2_15_prev_refused "$SCRIPT_SRC" expired; check "G2-15 a _PREV holding a non-pinned EXPIRED token: refused whatever its status, zero writes" $?
  row_g2_16_denied_prev_overwritten "$SCRIPT_SRC"; check "G2-16 a _PREV both endpoints deny (an earlier revoked token): state=denied, the swap keeps the old token there" $?
  row_g2_17_key_unreadable_on_resume "$SCRIPT_SRC"; check "G2-17 _PREV pinned and the <KEY> read fails: UNREADABLE re-run refusal, never KEY_UNEXPECTED" $?
  row_g2_r1_resume_after_prev "$SCRIPT_SRC"; check "G2-R1 re-run after the _PREV copy: copy-staged-token + delete only, no _PREV write, SWAPPED" $?
  row_g2_r2_resume_after_key "$SCRIPT_SRC"; check "G2-R2 re-run after the <KEY> write: delete-staging-key only, no write, SWAPPED" $?

  echo "== Guard 3: holder-copies =="
  row_g3_1_last_holder_bad "$SCRIPT_SRC" third; check "G3-1 the last holder (dev) holds a third value: refuse naming it, zero writes" $?
  row_g3_1_last_holder_bad "$SCRIPT_SRC" absent; check "G3-1 the last holder (dev) lacks the key: refuse naming it, zero writes" $?
  row_g3_2_second_already_new "$SCRIPT_SRC"; check "G3-2 first holder old, second already new: writes only the first" $?
  row_g3_3_before_swap "$SCRIPT_SRC"; check "G3-3 run before swap: PRECONDITION_FAILED need=swap" $?
  row_g3_4_nothing_swapped "$SCRIPT_SRC"; check "G3-4 nothing staged and no swap: need=swap, no holder classified as already done" $?
  row_g3_r1_resume_after_first_holder "$SCRIPT_SRC"; check "G3-R1 re-run after the first holder was copied: writes the second only" $?
  row_g3_5_copy_mismatch "$SCRIPT_SRC"; check "G3-5 the first holder copy does not read back equal: COPY_MISMATCH, the second holder untouched, stage fails" $?
  row_g3_6_source_unreadable_at_copy "$SCRIPT_SRC"; check "G3-6 the copy source stops reading after the plan: no holder write, stage fails" $?

  echo "== Test Scenarios =="
  row_s1_happy_path "$SCRIPT_SRC"; check "S1 happy path: swap, holder-copies, verify ok with three REVOKE_READY, revoke, inventory source=none, every write stage satisfied, no GitHub call" $?
  row_s2_account_owned "$SCRIPT_SRC"; check "S2 an account-owned new token (user endpoint refuses) reads as new and active" $?
  row_s3_unreachable "$SCRIPT_SRC"; check "S3 429 / 503 on a verify read is TOKEN_UNREACHABLE and the stage refuses, never a verdict" $?
  row_s4_no_receipt "$SCRIPT_SRC"; check "S4 an apply without a receipt exits 75 and writes nothing (swap and holder-copies)" $?
  row_s5_malformed_next "$SCRIPT_SRC" quote; check "S5 a staged value with a quote is refused before any curl call" $?
  row_s5_malformed_next "$SCRIPT_SRC" newline; check "S5 a staged value with an embedded newline is refused before any curl call" $?
  row_s6_analytics_api_error "$SCRIPT_SRC"; check "S6 ANALYTICS: zone-tag match plus an analytics-health api-error still reads ok" $?
  row_s7_graphql "$SCRIPT_SRC" mismatch; check "S7 ANALYTICS: a GraphQL answer without the new zone tag fails reason=consumer-read" $?
  row_s7_graphql "$SCRIPT_SRC" errors; check "S7 ANALYTICS: the new zone tag WITH a GraphQL error fails reason=consumer-read" $?
  row_s8_old_target_ids "$SCRIPT_SRC" zone; check "S8 prd_terraform still on the old zone id: target-ids-not-new, no consumer read" $?
  row_s8_old_target_ids "$SCRIPT_SRC" account; check "S8 prd_terraform on an account id that is not the new one: target-ids-not-new" $?
  row_s9_consumer_fails "$SCRIPT_SRC"; check "S9 one key's own consumer read fails: that key fails reason=consumer-read, the others stay ok" $?
  row_s3c_403_html "$SCRIPT_SRC"; check "S3 a 403 with an HTML body is TOKEN_UNREACHABLE http=403, never a denial" $?
  row_i1_reference_unreadable "$SCRIPT_SRC"; check "I-1 inventory: a reference that verifies but cannot be read is CENSUS_BLIND, exit non-zero" $?

  echo "== the environment, the trusted files and the manifest parser =="
  for _m in "${E1_VARS[@]}"; do
    row_e1_env_refused "$SCRIPT_SRC" var "$_m"; check "E1 ${_m} inherited: ENV_REFUSED name=${_m}, exit 64 before any doppler or curl call" $?
  done
  for _m in "${E1_FUNCS[@]}"; do
    row_e1_env_refused "$SCRIPT_SRC" function "$_m"; check "E1 ${_m} an exported shell function: ENV_REFUSED name=function:${_m}, exit 64 before any call" $?
  done
  row_e1_env_inert "$SCRIPT_SRC"; check "E1 GIT_EDITOR, GIT_SEQUENCE_EDITOR, GIT_PAGER, GIT_TERMINAL_PROMPT and GIT_CEILING_DIRECTORIES are not refused: verify ok" $?
  row_t1_dirty_file "$SCRIPT_SRC" tool; check "T1 an uncommitted edit to cloudflare-readonly.sh: UNTRUSTED_FILE, the wrapper never runs, no REVOKE_READY" $?
  row_t1_dirty_file "$SCRIPT_SRC" filter; check "T1 an edit a clean filter hides from a filtered hash: UNTRUSTED_FILE (hash-object --no-filters), no REVOKE_READY" $?
  row_t1_dirty_file "$SCRIPT_SRC" inventory; check "T1 an uncommitted edit to the inventory file: UNTRUSTED_FILE, FLOOR_MISSING, census-floor" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" tab; check "M1 a manifest line with a tab after the tag: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" indent; check "M1 a manifest line with an indented line: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" nospace; check "M1 a manifest line with #P5-MANIFEST without a space: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" fourth; check "M1 a manifest line with a fourth field: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" prefix; check "M1 a manifest line with a first holder soleur/prd_terraform_x: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" dupkey; check "M1 a manifest line with a duplicate key: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" suffix; check "M1 a manifest line with a key ending _PREV: MANIFEST_INVALID naming its file line, zero writes" $?
  row_m1_manifest_invalid "$SCRIPT_SRC" dupholder; check "M1 a manifest line with a duplicate holder: MANIFEST_INVALID naming its file line, zero writes" $?
  for _m in removed duplicated malformed; do
    row_f1_floor_line "$SCRIPT_SRC" "$_m"; check "F1 the P5-PROJECT-FLOOR line ${_m}: FLOOR_MISSING name=project-floor-line, census-floor, no REVOKE_READY" $?
  done

  echo "== the _PREV state and the revoked verdict (CTO D6) =="
  for _m in pinned denied other malformed unreadable unreachable absent; do
    row_p1_prev_state "$SCRIPT_SRC" "$_m"; check "P1 inventory and verify each print SOLEUR_P5_PREV key=${KA} state=${_m} exactly once" $?
  done
  row_v1_revoked "$SCRIPT_SRC"; check "V1 AUDIT revoked (no reference, _PREV denied): verdict=revoked, census value=revoked, no REVOKE_READY, the others still REVOKE_READY, its other checks still run" $?

  echo "== P-leak: no synthesized value, digest or full id in any output =="
  ! grep -qE 'SYNTH-|synth-actor|192\.0\.2\.7|injected\.invalid' "$ALL_OUT"
  check "no SYNTH-* value, consumer body field or injected URL appears in any stdout/stderr" $?
  leak_scan "$ALL_OUT"
  check "no digest or full id (24+ hex) appears on any line but the exact SOLEUR_BOOTSTRAP_PLAN digest line" $?
fi

# ==================================================================================================
# The instrument: the leak scanner and the mutant scorer must each be able to say no
# ==================================================================================================
echo "== instrument controls =="
LEAK_PLANT="$SB/leak-plant.log"; LEAK_CLEAN="$SB/leak-clean.log"
{ printf 'SOLEUR_P5_READBACK digest-check=%s\n' "$(printf 'plant' | sha256sum | cut -c1-64)"
  for _i in $(seq 1 3000); do printf 'SOLEUR_P5_HOLDER project=soleur config=dev key=CF_API_TOKEN_AUDIT value=new %s\n' "$_i"; done; } > "$LEAK_PLANT"
{ printf 'SOLEUR_BOOTSTRAP_PLAN stage=swap operations=3 digest=%s\n' "$(printf 'plan' | sha256sum | cut -c1-64)"; tail -n +2 "$LEAK_PLANT"; } > "$LEAK_CLEAN"
r=1; [[ "$(wc -c < "$LEAK_PLANT")" -gt 102400 ]] && ! leak_scan "$LEAK_PLANT" && r=0
check "control: a 64-hex line planted FIRST in a >100 KB log turns the leak scan red" "$r"
leak_scan "$LEAK_CLEAN"
check "control: the same log whose only 64-hex line is an exact SOLEUR_BOOTSTRAP_PLAN line passes the leak scan" $?

# score <row-fn> <src> <step> <why-ere> [<row-args>...] — rc 0 when the row went red as named (killed()).
# PRISTINE=1 (the --mutants pre-pass, testdesign S16): score runs the row's pristine arm instead, on the UNMUTATED
# script with no harness flag, once per distinct row and arguments, and records a red one; nothing is counted.
PRISTINE=0; PRISTINE_SEEN=" "; PRISTINE_RED=""; PRISTINE_N=0
score() {
  local fn="$1" src="$2" step="$3" why="$4" r; shift 4
  if [[ "$PRISTINE" -eq 1 ]]; then
    local id="${fn} $*" hf="$HARNESS_FLAG"
    [[ "$fn" != ctl_row && "$PRISTINE_SEEN" != *" ${id// /:} "* ]] || return 0
    PRISTINE_SEEN="${PRISTINE_SEEN}${id// /:} "
    HARNESS_FLAG=""; "$fn" "$SCRIPT_SRC" "$@" >/dev/null 2>&1; r=$?; HARNESS_FLAG="$hf"
    PRISTINE_N=$((PRISTINE_N + 1))
    [[ "$r" -eq 0 ]] || PRISTINE_RED="${PRISTINE_RED}    ${id} (step ${STEP}; ${WHY})"$'\n'
    return 0
  fi
  "$fn" "$src" "$@"; r=$?
  killed "$r" "$step" "$why"
}
# ctl_row <src> <step> <why> <rc> — a printf-and-exit stand-in for a row, for the scorer controls.
ctl_row() { at "$2"; WHY="$3"; printf '    control row: step=%s why=%s rc=%s\n' "$2" "$3" "$4"; return "$4"; }
! score ctl_row - named 'reason=wanted' named 'rc=0 reason=wanted ' 0 >/dev/null
check "control: the scorer rejects a row that stayed green (rc 0)" $?
! score ctl_row - named 'reason=wanted' elsewhere 'rc=1 reason=wanted ' 1 >/dev/null
check "control: the scorer rejects a row that went red at another step" $?
! score ctl_row - named 'reason=wanted' named 'rc=1 reason=other ' 1 >/dev/null
check "control: the scorer rejects a row that went red at the named step for another reason" $?
score ctl_row - named 'reason=wanted' named 'rc=1 reason=wanted ' 1 >/dev/null
check "control: the scorer accepts a row that went red at the named step with the named reason" $?

# ==================================================================================================
# Mutations and harness rows (full mode tail, and --mutants). ONE function, run twice under --mutants: first as
# the pristine pass (PRISTINE=1: every scored row's arm on the unmutated script, nothing counted), then scored.
# ==================================================================================================
mutate() { # <label> <dst> — perl program on stdin, applied to the real script by copy_with(); proves it landed
  local label="$1" dst="$2" r=0
  [[ "$PRISTINE" -eq 0 ]] || return 0
  copy_with "$SCRIPT_SRC" "$dst" || r=$?
  case "$r" in
    0) pass "mutation ${label} landed (differs from the source, bash -n clean)" ;;
    1) fail "mutation ${label} did not land"; return 1 ;;
    *) fail "mutation ${label} does not parse"; return 1 ;;
  esac
}
# mkill <label> <row-fn> <src> <step> <why-ere> [<row-args>...] — the row must go red AT <step> for <why>.
mkill() { local label="$1" r; shift; score "$@"; r=$?; [[ "$PRISTINE" -eq 1 ]] || check "${label} turns ${1#row_} RED at step ${3} (/${4}/)" "$r"; }
scored_section() {
echo "== mutations =="

if mutate G1M1 "$SB/g1m1.sh" <<'PERL'; then
s{  \[\[ "\$CT_FLOOR_OK" -eq 1 \]\] \|\| \{ vfail "\$k" census-floor; return 0; \}\n}{}
PERL
  mkill "G1M1 (census floor deleted)" row_g1_1_floor "$SB/g1m1.sh" verdict 'reason=census-blind'
  # The scorer's no-network control: the same mutant under a curl that never connects reds the same row at the
  # same step, but for another reason, and must NOT count as killed.
  if [[ "$PRISTINE" -eq 0 ]]; then
    HARNESS_FLAG=curl-down; ! score row_g1_1_floor "$SB/g1m1.sh" verdict 'reason=census-blind' >/dev/null; r=$?; HARNESS_FLAG=""
    check "control: G1M1 under a curl that never connects is NOT scored as killed (red for another reason)" "$r"
  fi
fi
if mutate G1M2 "$SB/g1m2.sh" <<'PERL'; then
s{  \[\[ "\$revoked" -eq 1 \]\] \|\| \[\[ "\$C_OLD" -eq 1 && "\$C_PREV_OLD" -eq 1 \]\] \|\| \{ vfail "\$k" census-blind; return 0; \}\n}{}
PERL
