if mutate G1M4 "$SB/g1m4.sh" <<'PERL'; then
s{  for t in \$\{CT\[\@\]\+"\$\{CT\[\@\]\}"\}; do\n}{  for t in \$\{MHOLD[\$i]\}; do\n}
